  movzu({
    id: 'generics',
    title: 'Generiklər',
    sectionId: 'generics',

    nezeri: [
      { level: 'junior', q: 'Generiklər nə üçündür?', opts: ['Kodu sürətləndirmək', 'Eyni kodu müxtəlif tiplərlə tip təhlükəsizliyini itirmədən işlətmək', 'Yaddaşa qənaət', 'Xəta idarəetməsi'], a: 1, exp: 'List<String> və List<Int> eyni koddan gəlir, amma kompilyator hər birində tipi yoxlayır. Beləliklə həm təkrar kod, həm də çevirmə səhvləri aradan qalxır.' },
      { level: 'junior', q: 'Generik funksiya necə elan olunur?', opts: ['fun ilkini<T>(s: List<T>)', 'fun <T> ilkini(s: List<T>)', 'generic fun ilkini(s: List)', 'fun ilkini(s: List<T>)'], a: 1, exp: 'Tip parametri fun açar sözündən dərhal sonra, funksiya adından ƏVVƏL elan olunur.' },
      { level: 'junior', q: 'Generik sinif necə elan olunur?', opts: ['class Qutu<T>(val deyer: T)', 'class <T> Qutu(val deyer: T)', 'generic class Qutu(val deyer: T)', 'class Qutu(T val deyer)'], a: 0, exp: 'Tip parametri sinif adından sonra bucaqlı mötərizədə yazılır və sinifin hər yerində işlədilə bilir.' },
      { level: 'junior', q: 'T hərfi nəyi ifadə edir?', opts: ['Konkret tipi', 'Tip parametrini — istənilən tip ola bilər', 'Mətn tipini', 'Xüsusi açar sözü'], a: 1, exp: 'T sadəcə adət olunmuş addır (Type). İstənilən ad işlədilə bilər: E (element), K/V (key/value), R (result).' },
      { level: 'junior', q: 'Qutu("Kotlin") çağırışında T nə olur?', opts: ['Any', 'String — kompilyator arqumentdən çıxarır', 'Object', 'Bilinmir'], a: 1, exp: 'Tip çıxarışı generiklərdə də işləyir. Açıq yazmaq da olar: Qutu<String>("Kotlin").' },
      { level: 'junior', q: 'Bu kodun nəticəsi nədir?', code: 'fun <T> ilkini(s: List<T>): T = s.first()\n\nfun main() {\n    println(ilkini(listOf(7, 8, 9)))\n}', opts: ['[7, 8, 9]', '7', '9', 'Kompilyasiya xətası'], a: 1, exp: 'T tipi Int kimi çıxarılır və funksiya siyahının ilk elementini qaytarır.' },
      { level: 'junior', q: 'Generik tipə məhdudiyyət necə qoyulur?', opts: ['fun <T : Comparable<T>> f(a: T)', 'fun <T extends Comparable> f(a: T)', 'fun <T where Comparable> f(a: T)', 'Mümkün deyil'], a: 0, exp: 'İki nöqtədən sonra üst hüdud yazılır. Bundan sonra T üzərində həmin tipin metodları işlədilə bilir.' },
      { level: 'junior', q: 'Məhdudiyyət yazılmasa T-nin üst hüdudu nə olur?', opts: ['Any', 'Any?', 'Nothing', 'Unit'], a: 1, exp: 'Defolt üst hüdud Any?-dir, yəni T nullable da ola bilər. Null olmayan tip tələb etmək üçün <T : Any> yazılır.' },
      { level: 'junior', q: 'Map<K, V> ifadəsində neçə tip parametri var?', opts: ['1', '2', '3', '0'], a: 1, exp: 'K açarın, V isə dəyərin tipidir. Bir sinifdə istənilən sayda tip parametri ola bilər.' },
      { level: 'middle', q: 'Bir neçə məhdudiyyət necə yazılır?', opts: ['<T : A, B>', 'where T : A, T : B', '<T : A & B>', 'Mümkün deyil'], a: 1, exp: 'Bir məhdudiyyət bucaqlı mötərizədə yazıla bilər, ikidən çoxu üçün funksiya imzasından sonra where bəndi işlədilir.' },
      { level: 'middle', q: 'out T nə deməkdir?', opts: ['T yalnız parametr kimi işlədilir', 'T yalnız qaytarılır — kovariantlıq', 'T dəyişkəndir', 'T məhduddur'], a: 1, exp: 'Kovariant tipdə Qutu<It> dəyəri Qutu<Heyvan> gözləyən yerə verilə bilir, çünki oxumaq təhlükəsizdir. List<out E> məhz belədir.' },
      { level: 'middle', q: 'in T nə deməkdir?', opts: ['T yalnız qaytarılır', 'T yalnız qəbul edilir — kontravariantlıq', 'T sabitdir', 'T nullable-dır'], a: 1, exp: 'Kontravariant tipdə Hedef<Heyvan> dəyəri Hedef<It> gözləyən yerə verilə bilir. Comparable<in T> buna nümunədir.' },
      { level: 'middle', q: 'MutableList<E> niyə invariantdır?', opts: ['Səhvən belədir', 'Həm oxunur, həm yazılır — kovariant olsaydı yanlış tip əlavə etmək olardı', 'Sürət üçün', 'Yaddaş üçün'], a: 1, exp: 'MutableList<It> dəyərini MutableList<Heyvan> kimi qəbul etsək, ora Pisik əlavə etmək mümkün olardı. Ona görə dəyişkən kolleksiyalar invariantdır.' },
      { level: 'middle', q: 'PECS qaydası nə deməkdir?', opts: ['Producer — out, Consumer — in', 'Producer — in, Consumer — out', 'Hər ikisi out', 'Hər ikisi in'], a: 0, exp: 'Tipdən yalnız oxuyursansa (producer) out, ona yalnız yazırsansa (consumer) in yaz. Hər ikisi lazımdırsa invariant qalır.' },
      { level: 'middle', q: 'Star projection (<*>) nə vaxt işlədilir?', opts: ['Tip parametri bilinməyəndə, amma nəyəsə olduğu bilinəndə', 'Həmişə', 'Yalnız Map ilə', 'Heç vaxt'], a: 0, exp: 'List<*> istənilən element tipli siyahını qəbul edir. Elementlər Any? kimi oxunur, əlavə etmək isə mümkün deyil.' },
      { level: 'middle', q: 'JVM-də generik tiplər çalışma vaxtı saxlanılırmı?', opts: ['Bəli', 'Xeyr — type erasure baş verir', 'Yalnız Kotlin-də', 'Yalnız data class-da'], a: 1, exp: 'Kompilyasiyadan sonra List<String> sadəcə List olur. Ona görə adi funksiyada x is T yazmaq mümkün deyil.' },
      { level: 'middle', q: 'reified nə üçün lazımdır?', opts: ['Sürət üçün', 'inline funksiyada tipi çalışma vaxtı əlçatan etmək üçün', 'Yaddaş üçün', 'Miras üçün'], a: 1, exp: 'inline funksiyanın gövdəsi çağırış yerinə köçürüldüyü üçün kompilyator T-ni konkret tiplə əvəz edə bilir. Belə olanda x is T və T::class işləyir.' },
      { level: 'middle', q: 'reified ilə birlikdə hansı açar söz məcburidir?', opts: ['open', 'inline', 'suspend', 'operator'], a: 1, exp: 'reified yalnız inline funksiyalarda mümkündür — mexanizm gövdənin çağırış yerinə açılmasına əsaslanır.' },
      { level: 'senior', q: 'Bu kodun nəticəsi nədir?', code: 'inline fun <reified T> List<*>.yalniz(): List<T> = filterIsInstance<T>()\n\nfun main() {\n    println(listOf(1, "a", 2).yalniz<Int>())\n}', opts: ['[1, a, 2]', '[1, 2]', '[a]', 'Kompilyasiya xətası'], a: 1, exp: 'reified sayəsində filterIsInstance konkret tipi bilir və yalnız Int elementləri seçir.' },
      { level: 'senior', q: 'List<Heyvan> dəyişəninə listOf<It>() vermək olarmı?', opts: ['Xeyr', 'Bəli — List kovariantdır (List<out E>)', 'Yalnız MutableList ilə', 'Yalnız boş siyahı ilə'], a: 1, exp: 'List yalnız oxuma interfeysidir, ona görə kovariant elan olunub. Bu, gündəlik kodda çox rahatlıq yaradır.' },
      { level: 'senior', q: 'Generik tipin nullable olmamasını necə tələb edirsən?', opts: ['<T : Any>', '<T : NotNull>', '<T!>', 'Mümkün deyil'], a: 0, exp: 'Any nullable olmayan bütün tiplərin atasıdır. <T : Any> yazsan T?-i qəbul edilmir.' },
      { level: 'senior', q: 'Generik genişlənmə funksiyası necə yazılır?', opts: ['fun List<T>.ikinci()', 'fun <T> List<T>.ikinci(): T?', 'fun <T> ikinci(List<T>)', 'extension fun List.ikinci()'], a: 1, exp: 'Tip parametri fun-dan sonra, receiver tipindən əvvəl elan olunur.' },
      { level: 'senior', q: 'out tipi funksiya parametri kimi işlətmək olarmı?', code: 'class Menbe<out T> {\n    fun yaz(x: T) { }\n}', opts: ['Bəli', 'Xeyr — kompilyasiya xətası verir', 'Yalnız private olanda', 'Yalnız inline olanda'], a: 1, exp: 'out tipin yalnız çıxışda olacağına zəmanət verir. Onu parametr kimi işlətmək bu zəmanəti pozardı, ona görə kompilyator icazə vermir. Yalnız private üzvlərdə istisna var.' },
      { level: 'senior', q: 'Generik sinifdə tip parametrindən obyekt yaratmaq olarmı (T())?', opts: ['Bəli', 'Xeyr — type erasure buna imkan vermir; fabrik lambda ötürülür', 'Yalnız data class ilə', 'Yalnız reified ilə'], a: 1, exp: 'Çalışma vaxtı T bilinmədiyi üçün konstruktor tapıla bilmir. Adətən () -> T tipli fabrik funksiyası parametr kimi ötürülür.' },
      { level: 'senior', q: 'Generik tiplərdə tip çıxarışı harada baş verir?', opts: ['Çalışma vaxtı', 'Kompilyasiya vaxtı — arqumentlərdən və ya gözlənilən tipdən', 'Heç vaxt', 'Yalnız reified ilə'], a: 1, exp: 'Kompilyator həm arqumentlərə, həm də nəticənin mənimsədildiyi dəyişənin tipinə baxaraq T-ni müəyyən edir.' }
    ],

    praktiki: [
      { level: 'junior', tapsiriq: 'Generik funksiya yaz: siyahının ilk elementini qaytarsın. Rəqəm siyahısı ilə çağır.', starter: 'fun main() {\n    println(ilkini(listOf(7, 8, 9)))\n}\n\n// generik funksiya yaz', gozlenilen: '7', ipucu: 'fun <T> ilkini(s: List<T>): T = s.first()', hell: 'fun main() {\n    println(ilkini(listOf(7, 8, 9)))\n}\n\nfun <T> ilkini(s: List<T>): T = s.first()' },
      { level: 'junior', tapsiriq: 'Eyni generik funksiyanı mətn siyahısı ilə çağır.', starter: 'fun <T> ilkini(s: List<T>): T = s.first()\n\nfun main() {\n    // metn siyahisi ile cagir\n}', gozlenilen: 'Kotlin', ipucu: 'println(ilkini(listOf("Kotlin", "Java")))', hell: 'fun <T> ilkini(s: List<T>): T = s.first()\n\nfun main() {\n    println(ilkini(listOf("Kotlin", "Java")))\n}' },
      { level: 'junior', tapsiriq: 'Generik sinif yaz: Qutu dəyəri saxlayıb qaytarsın.', starter: 'fun main() {\n    println(Qutu("Kotlin").al())\n}\n\n// generik sinif yaz', gozlenilen: 'Kotlin', ipucu: 'class Qutu<T>(private val deyer: T) { fun al(): T = deyer }', hell: 'fun main() {\n    println(Qutu("Kotlin").al())\n}\n\nclass Qutu<T>(private val deyer: T) {\n    fun al(): T = deyer\n}' },
      { level: 'junior', tapsiriq: 'Eyni generik sinifi rəqəmlə işlət.', starter: 'class Qutu<T>(private val deyer: T) {\n    fun al(): T = deyer\n}\n\nfun main() {\n    // reqemle isle\n}', gozlenilen: '42', ipucu: 'println(Qutu(42).al())', hell: 'class Qutu<T>(private val deyer: T) {\n    fun al(): T = deyer\n}\n\nfun main() {\n    println(Qutu(42).al())\n}' },
      { level: 'junior', tapsiriq: 'Tip arqumentini AÇIQ yaz: Qutu<String> yaradıb dəyəri çap et.', starter: 'class Qutu<T>(private val deyer: T) {\n    fun al(): T = deyer\n}\n\nfun main() {\n    // tipi acig yazaraq yarat\n}', gozlenilen: 'salam', ipucu: 'val q = Qutu<String>("salam")', hell: 'class Qutu<T>(private val deyer: T) {\n    fun al(): T = deyer\n}\n\nfun main() {\n    val q = Qutu<String>("salam")\n    println(q.al())\n}' },
      { level: 'junior', tapsiriq: 'İki tip parametrli sinif yaz: Cut açar və dəyər saxlasın.', starter: 'fun main() {\n    println(Cut("yas", 24).tesvir())\n}\n\n// iki tip parametrli sinif yaz', gozlenilen: 'yas=24', ipucu: 'class Cut<K, V>(val a: K, val b: V) { fun tesvir() = "$a=$b" }', hell: 'fun main() {\n    println(Cut("yas", 24).tesvir())\n}\n\nclass Cut<K, V>(val a: K, val b: V) {\n    fun tesvir() = "$a=$b"\n}' },
      { level: 'junior', tapsiriq: 'Generik funksiya ilə siyahının ölçüsünü qaytar.', starter: 'fun main() {\n    println(olcu(listOf("a", "b", "c")))\n}\n\n// generik funksiya yaz', gozlenilen: '3', ipucu: 'fun <T> olcu(s: List<T>) = s.size', hell: 'fun main() {\n    println(olcu(listOf("a", "b", "c")))\n}\n\nfun <T> olcu(s: List<T>) = s.size' },
      { level: 'junior', tapsiriq: 'Generik funksiya ilə iki dəyəri cütləşdirib çap et.', starter: 'fun main() {\n    println(cutle("ad", 24))\n}\n\n// generik funksiya yaz', gozlenilen: '(ad, 24)', ipucu: 'fun <A, B> cutle(a: A, b: B) = a to b', hell: 'fun main() {\n    println(cutle("ad", 24))\n}\n\nfun <A, B> cutle(a: A, b: B) = a to b' },
      { level: 'junior', tapsiriq: 'Generik funksiya siyahını tərsinə çevirsin.', starter: 'fun main() {\n    println(tersine(listOf(1, 2, 3)))\n}\n\n// generik funksiya yaz', gozlenilen: '[3, 2, 1]', ipucu: 'fun <T> tersine(s: List<T>) = s.reversed()', hell: 'fun main() {\n    println(tersine(listOf(1, 2, 3)))\n}\n\nfun <T> tersine(s: List<T>) = s.reversed()' },
      { level: 'middle', tapsiriq: 'Tip məhdudiyyəti qoy: Comparable tələb edən boyuk() funksiyası yaz.', starter: 'fun main() {\n    println(boyuk(9, 3))\n}\n\n// mehdudiyyetli generik funksiya yaz', gozlenilen: '9', ipucu: 'fun <T : Comparable<T>> boyuk(a: T, b: T) = if (a > b) a else b', hell: 'fun main() {\n    println(boyuk(9, 3))\n}\n\nfun <T : Comparable<T>> boyuk(a: T, b: T) = if (a > b) a else b' },
      { level: 'middle', tapsiriq: 'Eyni məhdudiyyətli funksiyanı mətnlərlə işlət.', starter: 'fun <T : Comparable<T>> boyuk(a: T, b: T) = if (a > b) a else b\n\nfun main() {\n    // metnlerle cagir\n}', gozlenilen: 'Kotlin', ipucu: 'println(boyuk("Java", "Kotlin")) — mətnlər əlifba sırası ilə müqayisə olunur.', hell: 'fun <T : Comparable<T>> boyuk(a: T, b: T) = if (a > b) a else b\n\nfun main() {\n    println(boyuk("Java", "Kotlin"))\n}' },
      { level: 'middle', tapsiriq: 'Null olmayan tip tələb et: <T : Any> ilə funksiya yaz.', starter: 'fun main() {\n    println(teleb("Kotlin"))\n}\n\n// <T : Any> mehdudiyyetli funksiya yaz', gozlenilen: 'Kotlin', ipucu: 'fun <T : Any> teleb(x: T): T = x', hell: 'fun main() {\n    println(teleb("Kotlin"))\n}\n\nfun <T : Any> teleb(x: T): T = x' },
      { level: 'middle', tapsiriq: 'Generik genişlənmə yaz: siyahının ikinci elementini təhlükəsiz qaytarsın.', starter: 'fun main() {\n    println(listOf(1, 2, 3).ikinci())\n}\n\n// generik genislenme yaz', gozlenilen: '2', ipucu: 'fun <T> List<T>.ikinci(): T? = getOrNull(1)', hell: 'fun main() {\n    println(listOf(1, 2, 3).ikinci())\n}\n\nfun <T> List<T>.ikinci(): T? = getOrNull(1)' },
      { level: 'middle', tapsiriq: 'Star projection işlət: istənilən siyahının ölçüsünü qaytaran funksiya yaz.', starter: 'fun main() {\n    println(say(listOf("a", "b")))\n}\n\n// star projection ile funksiya yaz', gozlenilen: '2', ipucu: 'fun say(s: List<*>) = s.size', hell: 'fun main() {\n    println(say(listOf("a", "b")))\n}\n\nfun say(s: List<*>) = s.size' },
      { level: 'middle', tapsiriq: 'Kovariantlığı göstər: List<String> dəyərini List<Any> dəyişəninə mənimsət və ölçünü çap et.', starter: 'fun main() {\n    val s = listOf("a", "b")\n    val a: List<Any> = // burani tamamla\n    println(a.size)\n}', gozlenilen: '2', ipucu: 'List kovariantdır — birbaşa mənimsətmək olar.', hell: 'fun main() {\n    val s = listOf("a", "b")\n    val a: List<Any> = s\n    println(a.size)\n}' },
      { level: 'middle', tapsiriq: 'Generik sinifə metod əlavə et: dəyəri çevirən map() yaz.', starter: 'class Qutu<T>(private val deyer: T) {\n    // <R> map metodunu yaz\n}\n\nfun main() {\n    println(Qutu(21).map { it * 2 })\n}', gozlenilen: '42', ipucu: 'fun <R> map(f: (T) -> R): R = f(deyer)', hell: 'class Qutu<T>(private val deyer: T) {\n    fun <R> map(f: (T) -> R): R = f(deyer)\n}\n\nfun main() {\n    println(Qutu(21).map { it * 2 })\n}' },
      { level: 'middle', tapsiriq: 'Generik funksiya ilə siyahını çevir: hər elementə funksiya tətbiq et.', starter: 'fun main() {\n    println(cevir(listOf(1, 2, 3)) { it * 10 })\n}\n\n// generik funksiya yaz', gozlenilen: '[10, 20, 30]', ipucu: 'fun <T, R> cevir(s: List<T>, f: (T) -> R): List<R> = s.map(f)', hell: 'fun main() {\n    println(cevir(listOf(1, 2, 3)) { it * 10 })\n}\n\nfun <T, R> cevir(s: List<T>, f: (T) -> R): List<R> = s.map(f)' },
      { level: 'middle', tapsiriq: 'where bəndi ilə iki məhdudiyyət yaz.', starter: 'fun main() {\n    println(emal("Kotlin"))\n}\n\n// where bendi ile funksiya yaz', gozlenilen: '[Kotlin]', ipucu: 'fun <T> emal(x: T): List<T> where T : Comparable<T>, T : Any = listOf(x)', hell: 'fun main() {\n    println(emal("Kotlin"))\n}\n\nfun <T> emal(x: T): List<T> where T : Comparable<T>, T : Any = listOf(x)' },
      { level: 'middle', tapsiriq: 'Generik Map yarat və dəyəri çap et.', starter: 'fun main() {\n    println(Lugat("ad", "Aysel").deyer)\n}\n\n// iki tip parametrli sinif yaz', gozlenilen: 'Aysel', ipucu: 'class Lugat<K, V>(val acar: K, val deyer: V)', hell: 'fun main() {\n    println(Lugat("ad", "Aysel").deyer)\n}\n\nclass Lugat<K, V>(val acar: K, val deyer: V)' },
      { level: 'senior', tapsiriq: 'reified işlət: qarışıq siyahıdan yalnız Int-ləri seç.', starter: 'fun main() {\n    println(listOf(1, "a", 2, "b").yalniz<Int>())\n}\n\n// inline + reified genislenme yaz', gozlenilen: '[1, 2]', ipucu: 'inline fun <reified T> List<*>.yalniz(): List<T> = filterIsInstance<T>()', hell: 'fun main() {\n    println(listOf(1, "a", 2, "b").yalniz<Int>())\n}\n\ninline fun <reified T> List<*>.yalniz(): List<T> = filterIsInstance<T>()' },
      { level: 'senior', tapsiriq: 'reified ilə tip yoxlaması yaz: dəyər String-dirmi?', starter: 'fun main() {\n    println(tipdirmi<String>("Kotlin"))\n}\n\n// inline + reified funksiya yaz', gozlenilen: 'true', ipucu: 'inline fun <reified T> tipdirmi(x: Any) = x is T', hell: 'fun main() {\n    println(tipdirmi<String>("Kotlin"))\n}\n\ninline fun <reified T> tipdirmi(x: Any) = x is T' },
      { level: 'senior', tapsiriq: 'reified ilə tip adını çap et.', starter: 'fun main() {\n    println(tipAdi<String>())\n}\n\n// inline + reified funksiya yaz', gozlenilen: 'String', ipucu: 'inline fun <reified T> tipAdi() = T::class.simpleName', hell: 'fun main() {\n    println(tipAdi<String>())\n}\n\ninline fun <reified T> tipAdi() = T::class.simpleName' },
      { level: 'senior', tapsiriq: 'Kovariant sinif yaz: out T ilə yalnız oxunan mənbə qur.', starter: 'fun main() {\n    val m: Menbe<Any> = Menbe("Kotlin")\n    println(m.al())\n}\n\n// out T ile sinif yaz', gozlenilen: 'Kotlin', ipucu: 'class Menbe<out T>(private val d: T) { fun al(): T = d }', hell: 'fun main() {\n    val m: Menbe<Any> = Menbe("Kotlin")\n    println(m.al())\n}\n\nclass Menbe<out T>(private val d: T) {\n    fun al(): T = d\n}' },
      { level: 'senior', tapsiriq: 'Kontravariant sinif yaz: in T ilə yalnız qəbul edən hədəf qur.', starter: 'fun main() {\n    val h: Hedef<String> = Hedef<Any>()\n    h.yaz("Kotlin")\n}\n\n// in T ile sinif yaz', gozlenilen: 'Kotlin', ipucu: 'class Hedef<in T> { fun yaz(x: T) = println(x) }', hell: 'fun main() {\n    val h: Hedef<String> = Hedef<Any>()\n    h.yaz("Kotlin")\n}\n\nclass Hedef<in T> {\n    fun yaz(x: T) = println(x)\n}' },
      { level: 'senior', tapsiriq: 'Fabrik lambda ilə generik obyekt yarat (T() mümkün olmadığı üçün).', starter: 'fun main() {\n    println(yarat { "yeni" })\n}\n\n// fabrik lambda qebul eden generik funksiya yaz', gozlenilen: 'yeni', ipucu: 'fun <T> yarat(fabrik: () -> T): T = fabrik()', hell: 'fun main() {\n    println(yarat { "yeni" })\n}\n\nfun <T> yarat(fabrik: () -> T): T = fabrik()' }
    ]
  });

  /* ==========================================================
     17 · İSTİSNALAR (exceptions)
     ========================================================== */
  movzu({
    id: 'istisnalar',
    title: 'İstisnalar (exceptions)',
    sectionId: 'istisnalar',

    nezeri: [
      { level: 'junior', q: 'Kotlin-də checked exception varmı?', opts: ['Bəli', 'Xeyr — heç bir metod throws elan etməyə məcbur deyil', 'Yalnız IOException üçün', 'Yalnız Java ilə işləyəndə'], a: 1, exp: 'Java-nın ən çox tənqid olunan xüsusiyyətindən imtina edilib. İstisna tutmaq və ya elan etmək tamamilə könüllüdür.' },
      { level: 'junior', q: 'İstisna necə atılır?', opts: ['raise Xeta()', 'throw Xeta()', 'error Xeta()', 'panic Xeta()'], a: 1, exp: 'throw açar sözü işlədilir. Kotlin-də throw ifadədir və tipi Nothing-dir.' },
      { level: 'junior', q: 'try blokunun hansı hissəsi HƏMİŞƏ işləyir?', opts: ['try', 'catch', 'finally', 'Heç biri'], a: 2, exp: 'finally istisna atılsa da, atılmasa da icra olunur. Resursları bağlamaq üçün işlədilir — amma Kotlin-də bunun üçün use() daha yaxşıdır.' },
      { level: 'junior', q: 'Kotlin-də try nədir?', opts: ['Yalnız operator', 'Dəyər qaytaran ifadə', 'Funksiya', 'Açar söz deyil'], a: 1, exp: 'val n = try { "42".toInt() } catch (e: Exception) { 0 } — try blokunun son ifadəsi nəticə olur.' },
      { level: 'junior', q: '"abc".toInt() nə edir?', opts: ['0 qaytarır', 'null qaytarır', 'NumberFormatException atır', '-1 qaytarır'], a: 2, exp: 'Çevirmə mümkün olmadıqda istisna atılır. Təhlükəsiz variant toIntOrNull()-dur.' },
      { level: 'junior', q: 'catch blokunda istisna tipi necə yazılır?', opts: ['catch (Exception e)', 'catch (e: Exception)', 'catch Exception', 'catch<Exception>'], a: 1, exp: 'Kotlin-də dəyişən adı əvvəl, tip sonra yazılır — funksiya parametrləri kimi.' },
      { level: 'junior', q: 'Bütün istisnaların ortaq atası hansıdır?', opts: ['Exception', 'Throwable', 'Error', 'RuntimeException'], a: 1, exp: 'Throwable-dan Exception və Error törəyir. Adətən Exception tutulur — Error sistem səviyyəli problemləri bildirir və tutulmamalıdır.' },
      { level: 'junior', q: 'Bu kodun nəticəsi nədir?', code: 'fun main() {\n    val n = try {\n        "abc".toInt()\n    } catch (e: NumberFormatException) {\n        -1\n    }\n    println(n)\n}', opts: ['abc', '0', '-1', 'İstisna atılır'], a: 2, exp: 'Çevirmə uğursuz olur, catch bloku işləyir və onun son ifadəsi (-1) nəticə olur.' },
      { level: 'junior', q: 'Bir try blokunda neçə catch ola bilər?', opts: ['1', '2', 'İstənilən qədər — müxtəlif tiplər üçün', '0'], a: 2, exp: 'Budaqlar yuxarıdan aşağı yoxlanılır. Daha spesifik tiplər yuxarıda yazılmalıdır, yoxsa ümumi tip onları udar.' },
      { level: 'middle', q: 'require() hansı istisnanı atır?', opts: ['IllegalStateException', 'IllegalArgumentException', 'NullPointerException', 'RuntimeException'], a: 1, exp: 'require() arqumentləri yoxlayır — giriş yanlışdırsa IllegalArgumentException atılır.' },
      { level: 'middle', q: 'check() hansı istisnanı atır?', opts: ['IllegalArgumentException', 'IllegalStateException', 'AssertionError', 'Exception'], a: 1, exp: 'check() obyektin daxili vəziyyətini yoxlayır. Vəziyyət yanlışdırsa IllegalStateException atılır.' },
      { level: 'middle', q: 'error("mesaj") nə edir?', opts: ['Mesajı çap edir', 'IllegalStateException atır', 'null qaytarır', 'Proqramı bitirir'], a: 1, exp: 'Qaytarma tipi Nothing-dir, ona görə elvis operatorunun sağ tərəfində işlədilə bilir: x ?: error("tapilmadi").' },
      { level: 'middle', q: 'TODO() nə edir?', opts: ['Şərh əlavə edir', 'NotImplementedError atır', 'Heç nə', 'Kodu atlayır'], a: 1, exp: 'Hələ yazılmamış kodu işarələmək üçündür. Tipi Nothing olduğu üçün istənilən qaytarma tipinin yerinə yazıla bilir.' },
      { level: 'middle', q: 'runCatching { } nə qaytarır?', opts: ['Boolean', 'Result<T>', 'T?', 'Unit'], a: 1, exp: 'Uğurlu nəticəni və ya tutulmuş istisnanı Result obyektində saxlayır. getOrNull(), getOrDefault(), onSuccess/onFailure ilə emal olunur.' },
      { level: 'middle', q: 'Öz istisnanı necə yaradırsan?', opts: ['class Xeta : Exception()', 'exception Xeta', 'throw class Xeta', 'error class Xeta'], a: 0, exp: 'Exception və ya onun varislərindən miras alınır. Mesaj konstruktora ötürülür: class Xeta(m: String) : Exception(m).' },
      { level: 'middle', q: 'Bu kodun nəticəsi nədir?', code: 'fun main() {\n    try {\n        println("A")\n        throw RuntimeException("x")\n    } catch (e: Exception) {\n        println("B")\n    } finally {\n        println("C")\n    }\n}', opts: ['A B C', 'A C', 'A B', 'B C'], a: 0, exp: 'try başlayır (A), istisna atılır, catch işləyir (B), sonra finally mütləq icra olunur (C).' },
      { level: 'middle', q: 'finally daxilində return yazmaq niyə təhlükəlidir?', opts: ['Təhlükəli deyil', 'Atılan istisnanı udur və səhvi gizlədir', 'Kompilyasiya xətası verir', 'Yavaş işləyir'], a: 1, exp: 'finally-dəki return istisnanı ləğv edir və funksiya normal qayıdır. Problem səssizcə itir — bu, çətin tapılan səhvlərə səbəb olur.' },
      { level: 'middle', q: 'use() funksiyası nə üçündür?', opts: ['Dəyişən yaratmaq', 'Closeable resursu avtomatik bağlamaq', 'İstisna atmaq', 'Tip çevirmək'], a: 1, exp: 'Java-dakı try-with-resources qarşılığıdır: fayl.use { ... } — blok bitəndə resurs istisna olsa da bağlanır.' },
      { level: 'senior', q: '@Throws annotasiyası nə üçündür?', opts: ['İstisnanı tutmaq', 'Java tərəfin checked exception görməsi üçün', 'İstisnanı gizlətmək', 'Performans üçün'], a: 1, exp: 'Kotlin-də checked exception yoxdur. Java kodunun try/catch tələb etməsini istəyirsənsə funksiyanı @Throws ilə işarələyirsən.' },
      { level: 'senior', q: 'Nə vaxt istisna, nə vaxt sealed nəticə tipi işlətmək lazımdır?', opts: ['Həmişə istisna', 'Gözlənilən uğursuzluqlar üçün sealed/Result, proqramçı səhvləri üçün istisna', 'Həmişə sealed', 'Fərqi yoxdur'], a: 1, exp: 'Şəbəkə yoxdur və ya validasiya pozulub — bunlar biznes məntiqinin hissəsidir və tiplə ifadə olunmalıdır. Pozulmuş konfiq və ya null id isə istisna tələb edir.' },
      { level: 'senior', q: 'Boş catch bloku niyə pisdir?', opts: ['Yavaşdır', 'Səhvi tamamilə gizlədir — problem sonra başqa yerdə üzə çıxır', 'Kompilyasiya xətası', 'Pis deyil'], a: 1, exp: 'İstisna udulursa proqram yanlış vəziyyətdə davam edir. Ən azı loglamaq və ya yenidən atmaq lazımdır.' },
      { level: 'senior', q: 'İstisnanı yenidən atmaq necə edilir?', opts: ['rethrow', 'throw e', 'return e', 'raise e'], a: 1, exp: 'catch blokunda emal etdikdən sonra throw e yazmaqla istisna yuxarı ötürülür. Coroutine-lərdə CancellationException mütləq belə ötürülməlidir.' },
      { level: 'senior', q: 'Result.fold() nə edir?', opts: ['Siyahını yığır', 'Uğur və uğursuzluq hallarını bir ifadədə emal edir', 'İstisna atır', 'Nəticəni çap edir'], a: 1, exp: 'fold(onSuccess = { ... }, onFailure = { ... }) — hər iki halı vahid yerdə emal edib tək dəyər qaytarır.' },
      { level: 'senior', q: 'throw ifadəsinin tipi nədir?', opts: ['Unit', 'Nothing', 'Exception', 'Any'], a: 1, exp: 'Nothing heç bir dəyəri olmayan tipdir və bütün tiplərin alt tipidir. Ona görə val x = y ?: throw Xeta() konstruksiyası tip yoxlamasından keçir.' },
      { level: 'senior', q: 'Ümumi catch (e: Exception) yazmaq nə vaxt problem yaradır?', opts: ['Heç vaxt', 'Gözlənilməyən səhvləri də udur və diaqnostikanı çətinləşdirir', 'Yalnız testlərdə', 'Kompilyasiya xətası verir'], a: 1, exp: 'Konkret tipi tutmaq daha yaxşıdır. Ümumi tutmaq lazımdırsa ən azı loglamaq və ya yenidən atmaq gərəkdir.' }
    ],

    praktiki: [
      { level: 'junior', tapsiriq: 'try/catch işlət: "abc" mətnini rəqəmə çevirməyə çalış, alınmasa -1 çap et.', starter: 'fun main() {\n    \n}', gozlenilen: '-1', ipucu: 'try { "abc".toInt() } catch (e: NumberFormatException) { -1 }', hell: 'fun main() {\n    val n = try {\n        "abc".toInt()\n    } catch (e: NumberFormatException) {\n        -1\n    }\n    println(n)\n}' },
      { level: 'junior', tapsiriq: 'Uğurlu çevirmədə try-ın öz nəticəsinin qayıtdığını göstər.', starter: 'fun main() {\n    val n = try {\n        "42".toInt()\n    } catch (e: NumberFormatException) {\n        -1\n    }\n    println(n)\n}', gozlenilen: '42', ipucu: 'Çevirmə uğurlu olduğu üçün catch işləmir.', hell: 'fun main() {\n    val n = try {\n        "42".toInt()\n    } catch (e: NumberFormatException) {\n        -1\n    }\n    println(n)\n}' },
      { level: 'junior', tapsiriq: 'finally blokunun həmişə işlədiyini göstər: üç sətir çap olunsun.', starter: 'fun main() {\n    try {\n        println("A")\n        throw RuntimeException("x")\n    } catch (e: Exception) {\n        // B cap et\n    } finally {\n        // C cap et\n    }\n}', gozlenilen: 'A\nB\nC', ipucu: 'catch daxilində println("B"), finally daxilində println("C").', hell: 'fun main() {\n    try {\n        println("A")\n        throw RuntimeException("x")\n    } catch (e: Exception) {\n        println("B")\n    } finally {\n        println("C")\n    }\n}' },
      { level: 'junior', tapsiriq: 'İstisnanın mesajını tutub çap et.', starter: 'fun main() {\n    try {\n        throw RuntimeException("problem var")\n    } catch (e: Exception) {\n        // mesaji cap et\n    }\n}', gozlenilen: 'problem var', ipucu: 'println(e.message)', hell: 'fun main() {\n    try {\n        throw RuntimeException("problem var")\n    } catch (e: Exception) {\n        println(e.message)\n    }\n}' },
      { level: 'junior', tapsiriq: 'toIntOrNull işlət: istisnasız yol seç, null halında 0 çap et.', starter: 'fun main() {\n    val s = "abc"\n    \n}', gozlenilen: '0', ipucu: 'println(s.toIntOrNull() ?: 0)', hell: 'fun main() {\n    val s = "abc"\n    println(s.toIntOrNull() ?: 0)\n}' },
      { level: 'junior', tapsiriq: 'İstisna at və tut: sıfıra bölmə üçün öz yoxlamanı yaz.', starter: 'fun main() {\n    try {\n        bol(10, 0)\n    } catch (e: IllegalArgumentException) {\n        println(e.message)\n    }\n}\n\n// bol funksiyasini yaz', gozlenilen: 'Sifira bolmek olmaz', ipucu: 'if (b == 0) throw IllegalArgumentException("Sifira bolmek olmaz")', hell: 'fun main() {\n    try {\n        bol(10, 0)\n    } catch (e: IllegalArgumentException) {\n        println(e.message)\n    }\n}\n\nfun bol(a: Int, b: Int): Int {\n    if (b == 0) throw IllegalArgumentException("Sifira bolmek olmaz")\n    return a / b\n}' },
      { level: 'junior', tapsiriq: 'İki catch budağı yaz: konkret tip yuxarıda olsun.', starter: 'fun main() {\n    try {\n        "abc".toInt()\n    } catch (e: NumberFormatException) {\n        // konkret\n    } catch (e: Exception) {\n        println("umumi")\n    }\n}', gozlenilen: 'reqem deyil', ipucu: 'Birinci catch daxilində println("reqem deyil").', hell: 'fun main() {\n    try {\n        "abc".toInt()\n    } catch (e: NumberFormatException) {\n        println("reqem deyil")\n    } catch (e: Exception) {\n        println("umumi")\n    }\n}' },
      { level: 'junior', tapsiriq: 'İstisna tipini çap et: hansı sinif atıldı?', starter: 'fun main() {\n    try {\n        "abc".toInt()\n    } catch (e: Exception) {\n        // tipin adini cap et\n    }\n}', gozlenilen: 'NumberFormatException', ipucu: 'println(e::class.simpleName)', hell: 'fun main() {\n    try {\n        "abc".toInt()\n    } catch (e: Exception) {\n        println(e::class.simpleName)\n    }\n}' },
      { level: 'junior', tapsiriq: 'Siyahıda olmayan indeksə müraciəti tut və "kenar" çap et.', starter: 'fun main() {\n    val s = listOf(1, 2)\n    try {\n        s[5]\n    } catch (e: IndexOutOfBoundsException) {\n        // cap et\n    }\n}', gozlenilen: 'kenar', ipucu: 'println("kenar")', hell: 'fun main() {\n    val s = listOf(1, 2)\n    try {\n        s[5]\n    } catch (e: IndexOutOfBoundsException) {\n        println("kenar")\n    }\n}' },
      { level: 'middle', tapsiriq: 'require() işlət: mənfi yaş üçün istisna atılsın, mesajı çap et.', starter: 'fun main() {\n    try {\n        yasQur(-5)\n    } catch (e: IllegalArgumentException) {\n        println(e.message)\n    }\n}\n\n// require ile funksiya yaz', gozlenilen: 'Yas menfi ola bilmez', ipucu: 'require(y >= 0) { "Yas menfi ola bilmez" }', hell: 'fun main() {\n    try {\n        yasQur(-5)\n    } catch (e: IllegalArgumentException) {\n        println(e.message)\n    }\n}\n\nfun yasQur(y: Int) {\n    require(y >= 0) { "Yas menfi ola bilmez" }\n}' },
      { level: 'middle', tapsiriq: 'check() işlət: vəziyyət yanlışdırsa IllegalStateException atılsın.', starter: 'fun main() {\n    try {\n        gonder(false)\n    } catch (e: IllegalStateException) {\n        println(e.message)\n    }\n}\n\n// check ile funksiya yaz', gozlenilen: 'Evvelce tesdiqle', ipucu: 'check(tesdiqli) { "Evvelce tesdiqle" }', hell: 'fun main() {\n    try {\n        gonder(false)\n    } catch (e: IllegalStateException) {\n        println(e.message)\n    }\n}\n\nfun gonder(tesdiqli: Boolean) {\n    check(tesdiqli) { "Evvelce tesdiqle" }\n}' },
      { level: 'middle', tapsiriq: 'error() işlət: çatılmaması gərəkən koda düşəndə istisna atılsın.', starter: 'fun main() {\n    try {\n        tap(99)\n    } catch (e: IllegalStateException) {\n        println(e.message)\n    }\n}\n\n// error ile funksiya yaz', gozlenilen: 'Tapilmadi', ipucu: 'fun tap(id: Int): String = if (id == 1) "var" else error("Tapilmadi")', hell: 'fun main() {\n    try {\n        tap(99)\n    } catch (e: IllegalStateException) {\n        println(e.message)\n    }\n}\n\nfun tap(id: Int): String = if (id == 1) "var" else error("Tapilmadi")' },
      { level: 'middle', tapsiriq: 'requireNotNull() işlət: null arqument üçün mesajı çap et.', starter: 'fun main() {\n    val x: String? = null\n    try {\n        // requireNotNull isle\n    } catch (e: IllegalArgumentException) {\n        println(e.message)\n    }\n}', gozlenilen: 'Deyer teleb olunur', ipucu: 'requireNotNull(x) { "Deyer teleb olunur" }', hell: 'fun main() {\n    val x: String? = null\n    try {\n        requireNotNull(x) { "Deyer teleb olunur" }\n    } catch (e: IllegalArgumentException) {\n        println(e.message)\n    }\n}' },
      { level: 'middle', tapsiriq: 'Öz istisna sinfini yarat və mesajını çap et.', starter: 'fun main() {\n    try {\n        throw BalansXetasi("Vesait catmir")\n    } catch (e: BalansXetasi) {\n        println(e.message)\n    }\n}\n\n// oz istisna sinfini yaz', gozlenilen: 'Vesait catmir', ipucu: 'class BalansXetasi(m: String) : Exception(m)', hell: 'fun main() {\n    try {\n        throw BalansXetasi("Vesait catmir")\n    } catch (e: BalansXetasi) {\n        println(e.message)\n    }\n}\n\nclass BalansXetasi(m: String) : Exception(m)' },
      { level: 'middle', tapsiriq: 'Öz istisnana əlavə sahə qoy: xəta kodunu çap et.', starter: 'fun main() {\n    try {\n        throw ApiXetasi("Server", 500)\n    } catch (e: ApiXetasi) {\n        println(e.kod)\n    }\n}\n\n// elave saheli istisna sinfi yaz', gozlenilen: '500', ipucu: 'class ApiXetasi(m: String, val kod: Int) : Exception(m)', hell: 'fun main() {\n    try {\n        throw ApiXetasi("Server", 500)\n    } catch (e: ApiXetasi) {\n        println(e.kod)\n    }\n}\n\nclass ApiXetasi(m: String, val kod: Int) : Exception(m)' },
      { level: 'middle', tapsiriq: 'runCatching işlət: uğurlu halda nəticəni çap et.', starter: 'fun main() {\n    val n = runCatching { "42".toInt() }\n    // getOrDefault ile cap et\n}', gozlenilen: '42', ipucu: 'println(n.getOrDefault(0))', hell: 'fun main() {\n    val n = runCatching { "42".toInt() }\n    println(n.getOrDefault(0))\n}' },
      { level: 'middle', tapsiriq: 'runCatching işlət: uğursuz halda ehtiyat dəyər çap et.', starter: 'fun main() {\n    val n = runCatching { "abc".toInt() }\n    \n}', gozlenilen: '0', ipucu: 'println(n.getOrDefault(0))', hell: 'fun main() {\n    val n = runCatching { "abc".toInt() }\n    println(n.getOrDefault(0))\n}' },
      { level: 'middle', tapsiriq: 'runCatching zəncirində map işlət: nəticəni ikiqat artırıb çap et.', starter: 'fun main() {\n    val n = runCatching { "21".toInt() }\n        // map ve getOrDefault elave et\n    println(n)\n}', gozlenilen: '42', ipucu: '.map { it * 2 }.getOrDefault(0)', hell: 'fun main() {\n    val n = runCatching { "21".toInt() }\n        .map { it * 2 }\n        .getOrDefault(0)\n    println(n)\n}' },
      { level: 'middle', tapsiriq: 'onSuccess və onFailure işlət: uğursuz halda mesajı çap et.', starter: 'fun main() {\n    runCatching { "abc".toInt() }\n        .onSuccess { println("ugur: $it") }\n        // onFailure elave et\n}', gozlenilen: 'ugursuz', ipucu: '.onFailure { println("ugursuz") }', hell: 'fun main() {\n    runCatching { "abc".toInt() }\n        .onSuccess { println("ugur: $it") }\n        .onFailure { println("ugursuz") }\n}' },
      { level: 'senior', tapsiriq: 'Result.fold() işlət: hər iki halı bir ifadədə emal et.', starter: 'fun main() {\n    val n = runCatching { "abc".toInt() }.fold(\n        // onSuccess ve onFailure yaz\n    )\n    println(n)\n}', gozlenilen: 'xeta', ipucu: 'fold(onSuccess = { "ugur" }, onFailure = { "xeta" })', hell: 'fun main() {\n    val n = runCatching { "abc".toInt() }.fold(\n        onSuccess = { "ugur" },\n        onFailure = { "xeta" }\n    )\n    println(n)\n}' },
      { level: 'senior', tapsiriq: 'Elvis ilə istisna at: null dəyər üçün mesajı tut və çap et.', starter: 'fun main() {\n    val x: String? = null\n    try {\n        val y = // elvis + throw yaz\n        println(y)\n    } catch (e: IllegalStateException) {\n        println(e.message)\n    }\n}', gozlenilen: 'bos deyer', ipucu: 'val y = x ?: throw IllegalStateException("bos deyer")', hell: 'fun main() {\n    val x: String? = null\n    try {\n        val y = x ?: throw IllegalStateException("bos deyer")\n        println(y)\n    } catch (e: IllegalStateException) {\n        println(e.message)\n    }\n}' },
      { level: 'senior', tapsiriq: 'İstisnanı yenidən at: catch-də logla, sonra yuxarı ötür və xaricdə tut.', starter: 'fun main() {\n    try {\n        daxili()\n    } catch (e: Exception) {\n        println("xaric: ${e.message}")\n    }\n}\n\nfun daxili() {\n    try {\n        throw RuntimeException("problem")\n    } catch (e: Exception) {\n        println("daxil: ${e.message}")\n        // yeniden at\n    }\n}', gozlenilen: 'daxil: problem\nxaric: problem', ipucu: 'catch blokunun sonunda throw e yaz.', hell: 'fun main() {\n    try {\n        daxili()\n    } catch (e: Exception) {\n        println("xaric: ${e.message}")\n    }\n}\n\nfun daxili() {\n    try {\n        throw RuntimeException("problem")\n    } catch (e: Exception) {\n        println("daxil: ${e.message}")\n        throw e\n    }\n}' },
      { level: 'senior', tapsiriq: 'sealed nəticə tipi ilə istisnasız xəta modeli qur.', starter: 'sealed class Cavab {\n    data class Ugur(val data: String) : Cavab()\n    data class Xeta(val kod: Int) : Cavab()\n}\n\nfun main() {\n    val c: Cavab = Cavab.Xeta(404)\n    // when ile emal et\n}', gozlenilen: 'Xeta: 404', ipucu: 'is Cavab.Xeta -> println("Xeta: ${c.kod}")', hell: 'sealed class Cavab {\n    data class Ugur(val data: String) : Cavab()\n    data class Xeta(val kod: Int) : Cavab()\n}\n\nfun main() {\n    val c: Cavab = Cavab.Xeta(404)\n    when (c) {\n        is Cavab.Ugur -> println("Ugur: ${c.data}")\n        is Cavab.Xeta -> println("Xeta: ${c.kod}")\n    }\n}' },
      { level: 'senior', tapsiriq: 'Nothing qaytaran funksiya yaz və istisnasını tut.', starter: 'fun main() {\n    try {\n        dayandir()\n    } catch (e: IllegalStateException) {\n        println(e.message)\n    }\n}\n\n// Nothing qaytaran funksiya yaz', gozlenilen: 'dayandirildi', ipucu: 'fun dayandir(): Nothing = error("dayandirildi")', hell: 'fun main() {\n    try {\n        dayandir()\n    } catch (e: IllegalStateException) {\n        println(e.message)\n    }\n}\n\nfun dayandir(): Nothing = error("dayandirildi")' },
      { level: 'senior', tapsiriq: 'İstisnanın səbəbini (cause) sarı: orijinal mesajı çap et.', starter: 'fun main() {\n    try {\n        try {\n            throw RuntimeException("kok sebeb")\n        } catch (e: Exception) {\n            // yeni istisnaya sar\n        }\n    } catch (e: Exception) {\n        println(e.cause?.message)\n    }\n}', gozlenilen: 'kok sebeb', ipucu: 'throw IllegalStateException("ust qat", e) — ikinci parametr cause-dur.', hell: 'fun main() {\n    try {\n        try {\n            throw RuntimeException("kok sebeb")\n        } catch (e: Exception) {\n            throw IllegalStateException("ust qat", e)\n        }\n    } catch (e: Exception) {\n        println(e.cause?.message)\n    }\n}' }
    ]
  });

