  movzu({
    id: 'coroutines',
    title: 'Coroutine-lər',
    sectionId: 'coroutines',

    nezeri: [
      { level: 'junior', q: 'Coroutine nədir?', opts: ['Yeni thread', 'Dayandırıla və davam etdirilə bilən yüngül tapşırıq', 'Sinif növü', 'Kitabxana'], a: 1, exp: 'Coroutine əməliyyat sistemi resursu tutmur. Bir neçə thread üzərində yüz minlərlə coroutine işləyə bilir.' },
      { level: 'junior', q: 'suspend açar sözü nə deməkdir?', opts: ['Funksiya heç nə qaytarmır', 'Funksiya dayandırıla bilər — yalnız coroutine daxilində çağırılır', 'Funksiya sinxrondur', 'Funksiya yeni thread yaradır'], a: 1, exp: 'suspend funksiya thread-i bloklamadan dayana bilir. Onu yalnız başqa suspend funksiyadan və ya coroutine builder-dən çağırmaq olar.' },
      { level: 'junior', q: 'delay() ilə Thread.sleep() arasındakı fərq nədir?', opts: ['Fərq yoxdur', 'delay thread-i bloklamır, sleep bloklayır', 'sleep daha dəqiqdir', 'delay yalnız Android-də var'], a: 1, exp: 'Bütün fərq buradadır: delay yalnız coroutine-i dayandırır, thread isə azad olub başqa coroutine-ləri işlədir.' },
      { level: 'junior', q: 'runBlocking nə edir?', opts: ['Coroutine yaradır və cari thread-i bloklayır', 'Coroutine-i ləğv edir', 'Yeni thread yaradır', 'Heç nə'], a: 0, exp: 'Adi koddan coroutine dünyasına körpüdür. main() və testlərdə işlədilir, istehsalat kodunda isə ondan qaçmaq lazımdır.' },
      { level: 'junior', q: 'launch nə qaytarır?', opts: ['Nəticəni', 'Job', 'Deferred', 'Unit'], a: 1, exp: 'launch «başlat və unut» üçündür — nəticə qaytarmır. Job ilə coroutine-i gözləmək (join) və ya ləğv etmək (cancel) olur.' },
      { level: 'junior', q: 'async nə qaytarır?', opts: ['Job', 'Deferred<T> — nəticə await() ilə alınır', 'Unit', 'Thread'], a: 1, exp: 'Deferred Job-un nəticə qaytaran variantıdır. await() nəticə hazır olana qədər thread-i bloklamadan gözləyir.' },
      { level: 'junior', q: 'suspend funksiyanı adi funksiyadan çağırmaq olarmı?', opts: ['Bəli', 'Xeyr — coroutine sahəsi lazımdır', 'Yalnız main()-dən', 'Yalnız Android-də'], a: 1, exp: 'Kompilyator xəta verir. Körpü kimi runBlocking və ya mövcud scope-un launch/async-i işlədilir.' },
      { level: 'junior', q: 'Bu kod nə çap edir?', code: 'import kotlinx.coroutines.*\n\nfun main() = runBlocking {\n    println("A")\n    delay(100)\n    println("B")\n}', opts: ['A B', 'B A', 'Yalnız A', 'Heç nə'], a: 0, exp: 'Kod ardıcıl icra olunur: A çap olunur, 100 ms gözlənilir, sonra B. delay thread-i bloklamır, sadəcə coroutine-i dayandırır.' },
      { level: 'junior', q: 'job.join() nə edir?', opts: ['Coroutine-i ləğv edir', 'Coroutine bitənə qədər gözləyir', 'Yeni coroutine yaradır', 'Nəticəni qaytarır'], a: 1, exp: 'Gözləmə thread-i bloklamır. Nəticə lazımdırsa async və await() işlədilir.' },
      { level: 'middle', q: 'İki async-i ardıcıl await etmək paralellik verirmi?', code: 'val a = async { getir() }\nval b = async { getir() }\nlistOf(a.await(), b.await())', opts: ['Xeyr', 'Bəli — async çağırılan kimi hər ikisi başlayır', 'Yalnız Dispatchers.IO ilə', 'Yalnız awaitAll ilə'], a: 1, exp: 'async dərhal işə salır, await isə sadəcə nəticəni gözləyir. Ona görə ümumi vaxt ən uzun tapşırıq qədər olur.' },
      { level: 'middle', q: 'coroutineScope nə edir?', opts: ['Thread yaradır', 'Bütün uşaq coroutine-lər bitənə qədər gözləyir', 'Coroutine-i ləğv edir', 'Dispatcher dəyişir'], a: 1, exp: 'Strukturlaşdırılmış konkurrentliyin əsasıdır: sahə bitmədən heç bir uşaq «itmiş» qalmır.' },
      { level: 'middle', q: 'Dispatchers.IO nə üçündür?', opts: ['CPU hesablamaları', 'Şəbəkə, fayl, verilənlər bazası — gözləmə çox olan işlər', 'UI yeniləmələri', 'Test üçün'], a: 1, exp: 'IO hovuzunda 64+ thread var, çünki bu işlər əsasən gözləyir. CPU-intensiv iş üçün Dispatchers.Default işlədilir.' },
      { level: 'middle', q: 'withContext nə edir?', opts: ['Yeni coroutine yaradır', 'Bloku başqa dispatcher-də işlədir və nəticəni qaytarır', 'Coroutine-i ləğv edir', 'Thread bloklayır'], a: 1, exp: 'Dispatcher dəyişmək üçün standart üsuldur: withContext(Dispatchers.IO) { faylOxu() }.' },
      { level: 'middle', q: 'Strukturlaşdırılmış konkurrentlik nə deməkdir?', opts: ['Coroutine-lər sıralı işləyir', 'Hər coroutine bir sahəyə aiddir və sahə ləğv olunanda hamısı dayanır', 'Thread-lər paylaşılır', 'Xətalar udulur'], a: 1, exp: 'Bu, «itmiş» tapşırıqların qarşısını alır. ViewModel məhv olanda viewModelScope-dakı bütün işlər avtomatik dayanır.' },
      { level: 'middle', q: 'Bu kod hansı ardıcıllıqla çap edir?', code: 'import kotlinx.coroutines.*\n\nfun main() = runBlocking {\n    launch { delay(200); println("B") }\n    launch { delay(100); println("A") }\n    println("S")\n}', opts: ['S A B', 'A B S', 'B A S', 'S B A'], a: 0, exp: 'launch bloklamır, ona görə əvvəlcə S çap olunur. Sonra gecikmələrə görə A (100 ms), daha sonra B (200 ms).' },
      { level: 'middle', q: 'withTimeoutOrNull vaxt bitdikdə nə qaytarır?', opts: ['İstisna atır', 'null', '0', 'Sonuncu dəyəri'], a: 1, exp: 'withTimeout istisna atır, withTimeoutOrNull isə null qaytarır — şərti emal üçün daha rahatdır.' },
      { level: 'middle', q: 'Flow nədir?', opts: ['Siyahı', 'Zamanla bir neçə dəyər buraxan asinxron axın', 'Thread', 'Dispatcher'], a: 1, exp: 'suspend funksiya bir dəyər qaytarır, Flow isə ardıcıl olaraq çoxlu dəyər buraxır. collect ilə oxunur.' },
      { level: 'middle', q: 'Flow-da hesablama nə vaxt başlayır?', opts: ['flow { } yaradılanda', 'collect çağırılanda', 'map çağırılanda', 'Dərhal'], a: 1, exp: 'Flow soyuqdur (cold) — terminal əməliyyat olan collect çağırılana qədər heç nə işləmir.' },
      { level: 'senior', q: 'Coroutine ləğvi necə işləyir?', opts: ['Dərhal dayandırılır', 'Əməkdaşlıq tələb edir — yalnız dayandırıla bilən nöqtədə baş verir', 'Thread öldürülür', 'İstisna atılır və udulur'], a: 1, exp: 'delay, yield, withContext kimi suspend nöqtələrində yoxlanılır. Uzun CPU dövründə suspend nöqtəsi yoxdursa ləğv işləmir — ensureActive() əlavə etmək lazımdır.' },
      { level: 'senior', q: 'catch blokunda tutulan CancellationException nə edilməlidir?', opts: ['Udulmalıdır', 'Yenidən atılmalıdır', 'Loglanmalıdır', 'Nəzərə alınmamalıdır'], a: 1, exp: 'Ləğvetmə mexanizmi bu istisnanın yuxarı ötürülməsinə əsaslanır. Udulsa coroutine ləğv olunmuş sayılmır və sahə gözləməkdə qalır.' },
      { level: 'senior', q: 'supervisorScope coroutineScope-dan nə ilə fərqlənir?', opts: ['Daha sürətlidir', 'Bir uşağın xətası digər uşaqları dayandırmır', 'Thread yaradır', 'Nəticə qaytarmır'], a: 1, exp: 'coroutineScope-da bir uşaq çökəndə bütün qardaşları ləğv olunur. supervisorScope-da isə hər uşaq müstəqildir.' },
      { level: 'senior', q: 'StateFlow ilə Flow arasındakı fərq nədir?', opts: ['Fərq yoxdur', 'StateFlow istidir və həmişə cari dəyəri saxlayır', 'Flow daha sürətlidir', 'StateFlow yalnız Android-də var'], a: 1, exp: 'StateFlow UI vəziyyəti üçündür — abunə olan dərhal son dəyəri alır. Bir dəfəlik hadisələr üçün SharedFlow işlədilir.' },
      { level: 'senior', q: 'runBlocking istehsalat kodunda niyə işlədilməməlidir?', opts: ['Yavaşdır', 'Cari thread-i bloklayır — coroutine-lərin bütün faydasını ləğv edir', 'Xəta verir', 'Yaddaş sızdırır'], a: 1, exp: 'Adı da bunu deyir. Yalnız main(), testlər və köhnə koda körpü üçün yerindədir.' },
      { level: 'senior', q: 'awaitAll() nə edir?', opts: ['Coroutine-ləri ləğv edir', 'Bir neçə Deferred-i birlikdə gözləyir', 'Yeni sahə yaradır', 'Dispatcher dəyişir'], a: 1, exp: 'listOf(a, b, c).awaitAll() — ardıcıl await yazmaqdan daha oxunaqlıdır və hər hansı biri çöksə dərhal xəta verir.' },
      { level: 'senior', q: 'yield() nə üçündür?', opts: ['Dəyər qaytarmaq', 'Növbəni digər coroutine-lərə vermək və ləğv nöqtəsi yaratmaq', 'Thread yaratmaq', 'Axını dayandırmaq'], a: 1, exp: 'Uzun hesablama dövründə yield() və ya ensureActive() çağırmaq ləğvetməyə imkan yaradır.' }
    ],

    praktiki: [
      { level: 'junior', tapsiriq: 'runBlocking işlət: iki sətri gecikmə ilə çap et.', starter: 'import kotlinx.coroutines.*\n\nfun main() = runBlocking {\n    println("A")\n    // 100 ms gozle\n    println("B")\n}', gozlenilen: 'A\nB', ipucu: 'delay(100) yaz — Thread.sleep deyil.', hell: 'import kotlinx.coroutines.*\n\nfun main() = runBlocking {\n    println("A")\n    delay(100)\n    println("B")\n}' },
      { level: 'junior', tapsiriq: 'suspend funksiya yaz və runBlocking-dən çağır.', starter: 'import kotlinx.coroutines.*\n\n// suspend funksiya yaz\n\nfun main() = runBlocking {\n    println(melumatAl())\n}', gozlenilen: 'melumat', ipucu: 'suspend fun melumatAl(): String { delay(50); return "melumat" }', hell: 'import kotlinx.coroutines.*\n\nsuspend fun melumatAl(): String {\n    delay(50)\n    return "melumat"\n}\n\nfun main() = runBlocking {\n    println(melumatAl())\n}' },
      { level: 'junior', tapsiriq: 'launch işlət: coroutine başlat və bitməsini gözlə.', starter: 'import kotlinx.coroutines.*\n\nfun main() = runBlocking {\n    val j = launch {\n        delay(50)\n        println("is bitdi")\n    }\n    // gozle\n    println("hamisi bitdi")\n}', gozlenilen: 'is bitdi\nhamisi bitdi', ipucu: 'j.join() yaz.', hell: 'import kotlinx.coroutines.*\n\nfun main() = runBlocking {\n    val j = launch {\n        delay(50)\n        println("is bitdi")\n    }\n    j.join()\n    println("hamisi bitdi")\n}' },
      { level: 'junior', tapsiriq: 'launch-un bloklamadığını göstər: gecikmələrə görə ardıcıllıq quraşdır.', starter: 'import kotlinx.coroutines.*\n\nfun main() = runBlocking {\n    launch { delay(200); println("B") }\n    launch { delay(100); println("A") }\n    // burada bir sey cap et\n}', gozlenilen: 'S\nA\nB', ipucu: 'println("S") yaz — launch bloklamadığı üçün o, birinci çıxır.', hell: 'import kotlinx.coroutines.*\n\nfun main() = runBlocking {\n    launch { delay(200); println("B") }\n    launch { delay(100); println("A") }\n    println("S")\n}' },
      { level: 'junior', tapsiriq: 'async işlət: nəticəni await ilə al və çap et.', starter: 'import kotlinx.coroutines.*\n\nfun main() = runBlocking {\n    val d = async {\n        delay(50)\n        42\n    }\n    // neticeni al ve cap et\n}', gozlenilen: '42', ipucu: 'println(d.await())', hell: 'import kotlinx.coroutines.*\n\nfun main() = runBlocking {\n    val d = async {\n        delay(50)\n        42\n    }\n    println(d.await())\n}' },
      { level: 'junior', tapsiriq: 'İki async ilə paralel iş gör və nəticələri birləşdirib çap et.', starter: 'import kotlinx.coroutines.*\n\nfun main() = runBlocking {\n    val a = async { delay(100); "A" }\n    val b = async { delay(100); "B" }\n    // neticeleri birlesdir\n}', gozlenilen: 'AB', ipucu: 'println("${a.await()}${b.await()}")', hell: 'import kotlinx.coroutines.*\n\nfun main() = runBlocking {\n    val a = async { delay(100); "A" }\n    val b = async { delay(100); "B" }\n    println("${a.await()}${b.await()}")\n}' },
      { level: 'junior', tapsiriq: 'repeat və delay birləşdir: üç dəfə say.', starter: 'import kotlinx.coroutines.*\n\nfun main() = runBlocking {\n    repeat(3) {\n        // indeksi cap et ve 30 ms gozle\n    }\n}', gozlenilen: '0\n1\n2', ipucu: 'println(it) sonra delay(30)', hell: 'import kotlinx.coroutines.*\n\nfun main() = runBlocking {\n    repeat(3) {\n        println(it)\n        delay(30)\n    }\n}' },
      { level: 'junior', tapsiriq: 'suspend funksiyanı ardıcıl iki dəfə çağır.', starter: 'import kotlinx.coroutines.*\n\nsuspend fun getir(ad: String): String {\n    delay(30)\n    return ad\n}\n\nfun main() = runBlocking {\n    // ardicil cagir ve cap et\n}', gozlenilen: 'A\nB', ipucu: 'println(getir("A")) sonra println(getir("B"))', hell: 'import kotlinx.coroutines.*\n\nsuspend fun getir(ad: String): String {\n    delay(30)\n    return ad\n}\n\nfun main() = runBlocking {\n    println(getir("A"))\n    println(getir("B"))\n}' },
      { level: 'junior', tapsiriq: 'Job-un aktiv olub-olmadığını yoxla: bitdikdən sonra vəziyyəti çap et.', starter: 'import kotlinx.coroutines.*\n\nfun main() = runBlocking {\n    val j = launch { delay(30) }\n    j.join()\n    // isCompleted xassesini cap et\n}', gozlenilen: 'true', ipucu: 'println(j.isCompleted)', hell: 'import kotlinx.coroutines.*\n\nfun main() = runBlocking {\n    val j = launch { delay(30) }\n    j.join()\n    println(j.isCompleted)\n}' },
      { level: 'middle', tapsiriq: 'coroutineScope işlət: bütün uşaqlar bitənə qədər gözləsin.', starter: 'import kotlinx.coroutines.*\n\nsuspend fun hamisi() = coroutineScope {\n    launch { delay(100); println("bir") }\n    launch { delay(150); println("iki") }\n}\n\nfun main() = runBlocking {\n    hamisi()\n    // sonda cap et\n}', gozlenilen: 'bir\niki\nbitdi', ipucu: 'println("bitdi") — coroutineScope uşaqları gözlədiyi üçün o, sonda çıxır.', hell: 'import kotlinx.coroutines.*\n\nsuspend fun hamisi() = coroutineScope {\n    launch { delay(100); println("bir") }\n    launch { delay(150); println("iki") }\n}\n\nfun main() = runBlocking {\n    hamisi()\n    println("bitdi")\n}' },
      { level: 'middle', tapsiriq: 'withContext işlət: bloku Default dispatcher-də işlədib nəticəni çap et.', starter: 'import kotlinx.coroutines.*\n\nfun main() = runBlocking {\n    val n = withContext(Dispatchers.Default) {\n        // 6 * 7 qaytarsin\n    }\n    println(n)\n}', gozlenilen: '42', ipucu: 'Blokun son ifadəsi nəticə olur.', hell: 'import kotlinx.coroutines.*\n\nfun main() = runBlocking {\n    val n = withContext(Dispatchers.Default) {\n        6 * 7\n    }\n    println(n)\n}' },
      { level: 'middle', tapsiriq: 'awaitAll işlət: üç Deferred-i birlikdə gözlə.', starter: 'import kotlinx.coroutines.*\n\nfun main() = runBlocking {\n    val a = async { delay(50); 1 }\n    val b = async { delay(50); 2 }\n    val c = async { delay(50); 3 }\n    // awaitAll ile cap et\n}', gozlenilen: '[1, 2, 3]', ipucu: 'println(listOf(a, b, c).awaitAll())', hell: 'import kotlinx.coroutines.*\n\nfun main() = runBlocking {\n    val a = async { delay(50); 1 }\n    val b = async { delay(50); 2 }\n    val c = async { delay(50); 3 }\n    println(listOf(a, b, c).awaitAll())\n}' },
      { level: 'middle', tapsiriq: 'withTimeoutOrNull işlət: vaxt bitdikdə null çap olunsun.', starter: 'import kotlinx.coroutines.*\n\nfun main() = runBlocking {\n    val n = withTimeoutOrNull(100) {\n        delay(500)\n        "bitdi"\n    }\n    println(n)\n}', gozlenilen: 'null', ipucu: 'Blok 500 ms çəkir, limit isə 100 ms — nəticə null olur.', hell: 'import kotlinx.coroutines.*\n\nfun main() = runBlocking {\n    val n = withTimeoutOrNull(100) {\n        delay(500)\n        "bitdi"\n    }\n    println(n)\n}' },
      { level: 'middle', tapsiriq: 'withTimeoutOrNull vaxtında bitdikdə nəticəni versin.', starter: 'import kotlinx.coroutines.*\n\nfun main() = runBlocking {\n    val n = withTimeoutOrNull(500) {\n        delay(50)\n        "bitdi"\n    }\n    println(n)\n}', gozlenilen: 'bitdi', ipucu: 'Blok limitdən tez bitir, ona görə real nəticə qayıdır.', hell: 'import kotlinx.coroutines.*\n\nfun main() = runBlocking {\n    val n = withTimeoutOrNull(500) {\n        delay(50)\n        "bitdi"\n    }\n    println(n)\n}' },
      { level: 'middle', tapsiriq: 'Flow yarat və collect ilə oxu.', starter: 'import kotlinx.coroutines.*\nimport kotlinx.coroutines.flow.*\n\nfun axin(): Flow<Int> = flow {\n    // 1, 2, 3 burax\n}\n\nfun main() = runBlocking {\n    axin().collect { println(it) }\n}', gozlenilen: '1\n2\n3', ipucu: 'for (i in 1..3) emit(i)', hell: 'import kotlinx.coroutines.*\nimport kotlinx.coroutines.flow.*\n\nfun axin(): Flow<Int> = flow {\n    for (i in 1..3) emit(i)\n}\n\nfun main() = runBlocking {\n    axin().collect { println(it) }\n}' },
      { level: 'middle', tapsiriq: 'Flow üzərində map işlət: hər dəyəri ikiqat artır.', starter: 'import kotlinx.coroutines.*\nimport kotlinx.coroutines.flow.*\n\nfun main() = runBlocking {\n    flowOf(1, 2, 3)\n        // map elave et\n        .collect { println(it) }\n}', gozlenilen: '2\n4\n6', ipucu: '.map { it * 2 }', hell: 'import kotlinx.coroutines.*\nimport kotlinx.coroutines.flow.*\n\nfun main() = runBlocking {\n    flowOf(1, 2, 3)\n        .map { it * 2 }\n        .collect { println(it) }\n}' },
      { level: 'middle', tapsiriq: 'Flow-da filter və map zənciri qur.', starter: 'import kotlinx.coroutines.*\nimport kotlinx.coroutines.flow.*\n\nfun main() = runBlocking {\n    flowOf(1, 2, 3, 4)\n        // yalniz cutleri sec ve 10-a vur\n        .collect { println(it) }\n}', gozlenilen: '20\n40', ipucu: '.filter { it % 2 == 0 }.map { it * 10 }', hell: 'import kotlinx.coroutines.*\nimport kotlinx.coroutines.flow.*\n\nfun main() = runBlocking {\n    flowOf(1, 2, 3, 4)\n        .filter { it % 2 == 0 }\n        .map { it * 10 }\n        .collect { println(it) }\n}' },
      { level: 'middle', tapsiriq: 'Flow-u siyahıya çevir və çap et.', starter: 'import kotlinx.coroutines.*\nimport kotlinx.coroutines.flow.*\n\nfun main() = runBlocking {\n    val s = flowOf(1, 2, 3)\n        // siyahiya cevir\n    println(s)\n}', gozlenilen: '[1, 2, 3]', ipucu: '.toList() terminal əməliyyatdır.', hell: 'import kotlinx.coroutines.*\nimport kotlinx.coroutines.flow.*\n\nfun main() = runBlocking {\n    val s = flowOf(1, 2, 3).toList()\n    println(s)\n}' },
      { level: 'middle', tapsiriq: 'onCompletion işlət: axın bitəndə mesaj çap olunsun.', starter: 'import kotlinx.coroutines.*\nimport kotlinx.coroutines.flow.*\n\nfun main() = runBlocking {\n    flowOf(1, 2)\n        // onCompletion elave et\n        .collect { println(it) }\n}', gozlenilen: '1\n2\naxin bitdi', ipucu: '.onCompletion { println("axin bitdi") }', hell: 'import kotlinx.coroutines.*\nimport kotlinx.coroutines.flow.*\n\nfun main() = runBlocking {\n    flowOf(1, 2)\n        .onCompletion { println("axin bitdi") }\n        .collect { println(it) }\n}' },
      { level: 'senior', tapsiriq: 'Ləğvetməni göstər: coroutine-i dayandır və finally blokunun işlədiyini yoxla.', starter: 'import kotlinx.coroutines.*\n\nfun main() = runBlocking {\n    val j = launch {\n        try {\n            repeat(100) {\n                println("is $it")\n                delay(100)\n            }\n        } finally {\n            // temizlik cap et\n        }\n    }\n    delay(250)\n    j.cancelAndJoin()\n    println("bitdi")\n}', gozlenilen: 'is 0\nis 1\nis 2\ntemizlik\nbitdi', ipucu: 'finally daxilində println("temizlik") yaz.', hell: 'import kotlinx.coroutines.*\n\nfun main() = runBlocking {\n    val j = launch {\n        try {\n            repeat(100) {\n                println("is $it")\n                delay(100)\n            }\n        } finally {\n            println("temizlik")\n        }\n    }\n    delay(250)\n    j.cancelAndJoin()\n    println("bitdi")\n}' },
      { level: 'senior', tapsiriq: 'isActive yoxla: ləğvdən sonra vəziyyəti çap et.', starter: 'import kotlinx.coroutines.*\n\nfun main() = runBlocking {\n    val j = launch { delay(1000) }\n    j.cancel()\n    // isActive xassesini cap et\n}', gozlenilen: 'false', ipucu: 'println(j.isActive)', hell: 'import kotlinx.coroutines.*\n\nfun main() = runBlocking {\n    val j = launch { delay(1000) }\n    j.cancel()\n    println(j.isActive)\n}' },
      { level: 'senior', tapsiriq: 'supervisorScope işlət: bir uşaq çöksə də digəri işləsin. DİQQƏT: main-i blok gövdəsi ilə yaz.', starter: 'import kotlinx.coroutines.*\n\nfun main() {\n    runBlocking {\n        supervisorScope {\n            launch {\n                try {\n                    throw RuntimeException("cokdu")\n                } catch (e: RuntimeException) {\n                    println("birinci ugursuz")\n                }\n            }\n            launch {\n                delay(100)\n                // ikinci ugurlu cap et\n            }\n        }\n    }\n}', gozlenilen: 'birinci ugursuz\nikinci ugurlu', ipucu: 'println("ikinci ugurlu"). Blok gövdəsi ona görə lazımdır ki, son ifadə Job qaytarır — "fun main() = runBlocking { }" formasında main-in tipi Job olur və JVM onu giriş nöqtəsi saymır.', hell: 'import kotlinx.coroutines.*\n\nfun main() {\n    runBlocking {\n        supervisorScope {\n            launch {\n                try {\n                    throw RuntimeException("cokdu")\n                } catch (e: RuntimeException) {\n                    println("birinci ugursuz")\n                }\n            }\n            launch {\n                delay(100)\n                println("ikinci ugurlu")\n            }\n        }\n    }\n}' },
      { level: 'senior', tapsiriq: 'try/catch ilə coroutine xətasını tut.', starter: 'import kotlinx.coroutines.*\n\nfun main() {\n    runBlocking {\n        try {\n            coroutineScope {\n                launch { throw RuntimeException("xeta var") }\n            }\n        } catch (e: Exception) {\n            // mesaji cap et\n        }\n    }\n}', gozlenilen: 'xeta var', ipucu: 'println(e.message). Uşaq coroutine çökəndə coroutineScope xətanı yuxarı ötürür, ona görə try/catch onu tuta bilir.', hell: 'import kotlinx.coroutines.*\n\nfun main() {\n    runBlocking {\n        try {\n            coroutineScope {\n                launch { throw RuntimeException("xeta var") }\n            }\n        } catch (e: Exception) {\n            println(e.message)\n        }\n    }\n}' },
      { level: 'senior', tapsiriq: 'yield() işlət: iki coroutine növbə ilə işləsin.', starter: 'import kotlinx.coroutines.*\n\nfun main() {\n    runBlocking {\n        launch {\n            println("A1")\n            yield()\n            println("A2")\n        }\n        launch {\n            println("B1")\n            // novbeni ver\n            println("B2")\n        }\n    }\n}', gozlenilen: 'A1\nB1\nA2\nB2', ipucu: 'yield() yaz — növbəni digər coroutine-ə verir.', hell: 'import kotlinx.coroutines.*\n\nfun main() {\n    runBlocking {\n        launch {\n            println("A1")\n            yield()\n            println("A2")\n        }\n        launch {\n            println("B1")\n            yield()\n            println("B2")\n        }\n    }\n}' },
      { level: 'senior', tapsiriq: 'async xətasını supervisorScope daxilində tut — adi sahədə xəta valideynə yayılır və proqram çökür.', starter: 'import kotlinx.coroutines.*\n\nfun main() {\n    runBlocking {\n        supervisorScope {\n            val d = async { throw RuntimeException("async xetasi") }\n            try {\n                d.await()\n            } catch (e: Exception) {\n                // mesaji cap et\n            }\n        }\n    }\n}', gozlenilen: 'async xetasi', ipucu: 'println(e.message). supervisorScope vacibdir: adi coroutineScope-da async-in xətası await-dən asılı olmayaraq valideyn sahəni ləğv edir və tutulsa belə proqram çökür.', hell: 'import kotlinx.coroutines.*\n\nfun main() {\n    runBlocking {\n        supervisorScope {\n            val d = async { throw RuntimeException("async xetasi") }\n            try {\n                d.await()\n            } catch (e: Exception) {\n                println(e.message)\n            }\n        }\n    }\n}' }
    ]
  });

