      { level: 'senior', tapsiriq: 'Mürəkkəb zənciri oxunaqlı et: aralıq nəticəyə ad ver.', starter: 'data class Isci(val ad: String, val sobe: String, val maas: Int)\n\nfun main() {\n    val i = listOf(\n        Isci("Aysel", "IT", 3000),\n        Isci("Kamran", "IT", 3500),\n        Isci("Leyla", "Satis", 2000)\n    )\n    // IT sobesinin orta maasini hesabla\n}', gozlenilen: '3250.0', ipucu: 'Aralıq dəyişənə ad ver: val itcilar = i.filter { it.sobe == "IT" }', hell: 'data class Isci(val ad: String, val sobe: String, val maas: Int)\n\nfun main() {\n    val i = listOf(\n        Isci("Aysel", "IT", 3000),\n        Isci("Kamran", "IT", 3500),\n        Isci("Leyla", "Satis", 2000)\n    )\n    val itcilar = i.filter { it.sobe == "IT" }\n    val ortaMaas = itcilar.map { it.maas }.average()\n    println(ortaMaas)\n}' }
