    praktiki: [
      { level: 'junior', tapsiriq: 'UI vəziyyətini sealed interface ilə modelləşdir və yüklənmə halını çap et.', starter: 'sealed interface EkranVeziyyeti {\n    // Yuklenir, Ugurlu(data), Xeta(mesaj) yaz\n}\n\nfun main() {\n    val v: EkranVeziyyeti = EkranVeziyyeti.Yuklenir\n    println(v)\n}', gozlenilen: 'Yuklenir', ipucu: 'data object Yuklenir : EkranVeziyyeti — data object aydın toString verir.', hell: 'sealed interface EkranVeziyyeti {\n    data object Yuklenir : EkranVeziyyeti\n    data class Ugurlu(val data: String) : EkranVeziyyeti\n    data class Xeta(val mesaj: String) : EkranVeziyyeti\n}\n\nfun main() {\n    val v: EkranVeziyyeti = EkranVeziyyeti.Yuklenir\n    println(v)\n}' },
      { level: 'junior', tapsiriq: 'Vəziyyəti when ilə emal et: hər hal üçün UI mətni qaytar.', starter: 'sealed interface V {\n    data object Yuklenir : V\n    data class Ugurlu(val d: String) : V\n    data class Xeta(val m: String) : V\n}\n\nfun ekran(v: V): String = when (v) {\n    // butun hallari emal et\n}\n\nfun main() {\n    println(ekran(V.Xeta("sebeke yoxdur")))\n}', gozlenilen: 'Xeta: sebeke yoxdur', ipucu: 'is V.Xeta -> "Xeta: ${v.m}"', hell: 'sealed interface V {\n    data object Yuklenir : V\n    data class Ugurlu(val d: String) : V\n    data class Xeta(val m: String) : V\n}\n\nfun ekran(v: V): String = when (v) {\n    V.Yuklenir -> "Yuklenir..."\n    is V.Ugurlu -> "Data: ${v.d}"\n    is V.Xeta -> "Xeta: ${v.m}"\n}\n\nfun main() {\n    println(ekran(V.Xeta("sebeke yoxdur")))\n}' },
      { level: 'junior', tapsiriq: 'Sadə sayğac vəziyyəti qur (Compose-dakı remember nümunəsinin modeli).', starter: 'class Sayqac {\n    // veziyyet ve artir() yaz\n}\n\nfun main() {\n    val s = Sayqac()\n    s.artir()\n    s.artir()\n    println(s.deyer)\n}', gozlenilen: '2', ipucu: 'var deyer = 0 və fun artir() { deyer++ }', hell: 'class Sayqac {\n    var deyer = 0\n        private set\n    fun artir() { deyer++ }\n}\n\nfun main() {\n    val s = Sayqac()\n    s.artir()\n    s.artir()\n    println(s.deyer)\n}' },
      { level: 'junior', tapsiriq: 'Android genişlənməsinin modelini yaz: View əvəzinə sadə sinifə gorunsun() əlavə et.', starter: 'class View {\n    var gorunur = false\n}\n\n// genislenme yaz\n\nfun main() {\n    val v = View()\n    v.gorunsun()\n    println(v.gorunur)\n}', gozlenilen: 'true', ipucu: 'fun View.gorunsun() { gorunur = true }', hell: 'class View {\n    var gorunur = false\n}\n\nfun View.gorunsun() {\n    gorunur = true\n}\n\nfun main() {\n    val v = View()\n    v.gorunsun()\n    println(v.gorunur)\n}' },
      { level: 'junior', tapsiriq: 'DTO-nu model sinfinə çevir (Retrofit cavabının emalı nümunəsi).', starter: 'data class IstifadeciDto(val id: Int, val ad: String)\ndata class Istifadeci(val ad: String)\n\n// cevirme funksiyasini yaz\n\nfun main() {\n    println(IstifadeciDto(1, "Aysel").toModel())\n}', gozlenilen: 'Istifadeci(ad=Aysel)', ipucu: 'fun IstifadeciDto.toModel() = Istifadeci(ad)', hell: 'data class IstifadeciDto(val id: Int, val ad: String)\ndata class Istifadeci(val ad: String)\n\nfun IstifadeciDto.toModel() = Istifadeci(ad)\n\nfun main() {\n    println(IstifadeciDto(1, "Aysel").toModel())\n}' },
      { level: 'junior', tapsiriq: 'Siyahını UI üçün hazırla: DTO siyahısını model siyahısına çevir.', starter: 'data class Dto(val ad: String)\ndata class Model(val ad: String)\n\nfun main() {\n    val s = listOf(Dto("a"), Dto("b"))\n    // map ile cevir ve adlari cap et\n}', gozlenilen: '[a, b]', ipucu: 's.map { Model(it.ad) }.map { it.ad }', hell: 'data class Dto(val ad: String)\ndata class Model(val ad: String)\n\nfun main() {\n    val s = listOf(Dto("a"), Dto("b"))\n    println(s.map { Model(it.ad) }.map { it.ad })\n}' },
      { level: 'junior', tapsiriq: 'Boş siyahı halını emal et: UI-da "melumat yoxdur" göstər.', starter: 'fun ekran(s: List<String>): String {\n    // bos olanda "melumat yoxdur"\n}\n\nfun main() {\n    println(ekran(emptyList()))\n}', gozlenilen: 'melumat yoxdur', ipucu: 'if (s.isEmpty()) "melumat yoxdur" else s.joinToString()', hell: 'fun ekran(s: List<String>): String {\n    return if (s.isEmpty()) "melumat yoxdur" else s.joinToString()\n}\n\nfun main() {\n    println(ekran(emptyList()))\n}' },
      { level: 'junior', tapsiriq: 'Context.toast() genişlənməsinin modelini yaz.', starter: 'class Context\n\n// toast genislenmesini yaz\n\nfun main() {\n    Context().toast("salam")\n}', gozlenilen: 'TOAST: salam', ipucu: 'fun Context.toast(m: String) = println("TOAST: $m")', hell: 'class Context\n\nfun Context.toast(m: String) = println("TOAST: $m")\n\nfun main() {\n    Context().toast("salam")\n}' },
      { level: 'junior', tapsiriq: 'dp çevirməsinin modelini yaz: rəqəmi piksellərə çevir (sıxlıq 2).', starter: '// dp genislenmesini yaz (sixliq 2)\n\nfun main() {\n    println(16.dp())\n}', gozlenilen: '32', ipucu: 'fun Int.dp() = this * 2', hell: 'fun Int.dp() = this * 2\n\nfun main() {\n    println(16.dp())\n}' },
      { level: 'middle', tapsiriq: 'ViewModel modelini qur: vəziyyəti yalnız daxildən dəyişən sinif yaz.', starter: 'class ViewModel {\n    // veziyyet xassesi (kenardan oxunan, daxilden deyisen) ve yukle() yaz\n}\n\nfun main() {\n    val vm = ViewModel()\n    println(vm.veziyyet)\n    vm.yukle()\n    println(vm.veziyyet)\n}', gozlenilen: 'Yuklenir\nHazir', ipucu: 'var veziyyet = "Yuklenir"\n    private set — sonra yukle() içində dəyişdir.', hell: 'class ViewModel {\n    var veziyyet = "Yuklenir"\n        private set\n\n    fun yukle() {\n        veziyyet = "Hazir"\n    }\n}\n\nfun main() {\n    val vm = ViewModel()\n    println(vm.veziyyet)\n    vm.yukle()\n    println(vm.veziyyet)\n}' },
      { level: 'middle', tapsiriq: 'Müşahidə olunan vəziyyət modeli qur: dəyişəndə abunəçiyə xəbər versin.', starter: 'class Veziyyet(baslangic: String) {\n    private var dinleyici: ((String) -> Unit)? = null\n    var deyer = baslangic\n        set(v) {\n            field = v\n            // dinleyicini cagir\n        }\n    fun izle(f: (String) -> Unit) { dinleyici = f }\n}\n\nfun main() {\n    val v = Veziyyet("bos")\n    v.izle { println("yeni: $it") }\n    v.deyer = "hazir"\n}', gozlenilen: 'yeni: hazir', ipucu: 'dinleyici?.invoke(v)', hell: 'class Veziyyet(baslangic: String) {\n    private var dinleyici: ((String) -> Unit)? = null\n    var deyer = baslangic\n        set(v) {\n            field = v\n            dinleyici?.invoke(v)\n        }\n    fun izle(f: (String) -> Unit) { dinleyici = f }\n}\n\nfun main() {\n    val v = Veziyyet("bos")\n    v.izle { println("yeni: $it") }\n    v.deyer = "hazir"\n}' },
      { level: 'middle', tapsiriq: 'Repository modelini qur: interfeys arxasında məlumat mənbəyi gizlət.', starter: 'interface Repo {\n    fun hamisi(): List<String>\n}\n\n// saxta implementasiya yaz\n\nfun main() {\n    val r: Repo = SaxtaRepo()\n    println(r.hamisi())\n}', gozlenilen: '[Aysel, Kamran]', ipucu: 'class SaxtaRepo : Repo { override fun hamisi() = listOf("Aysel", "Kamran") }', hell: 'interface Repo {\n    fun hamisi(): List<String>\n}\n\nclass SaxtaRepo : Repo {\n    override fun hamisi() = listOf("Aysel", "Kamran")\n}\n\nfun main() {\n    val r: Repo = SaxtaRepo()\n    println(r.hamisi())\n}' },
      { level: 'middle', tapsiriq: 'Dependency injection modelini qur: asılılığı konstruktordan ötür.', starter: 'interface Repo { fun al(): String }\n\nclass ViewModel(private val repo: Repo) {\n    // yukle() metodunu yaz\n}\n\nfun main() {\n    val saxta = object : Repo { override fun al() = "test" }\n    println(ViewModel(saxta).yukle())\n}', gozlenilen: 'TEST', ipucu: 'fun yukle() = repo.al().uppercase()', hell: 'interface Repo { fun al(): String }\n\nclass ViewModel(private val repo: Repo) {\n    fun yukle() = repo.al().uppercase()\n}\n\nfun main() {\n    val saxta = object : Repo { override fun al() = "test" }\n    println(ViewModel(saxta).yukle())\n}' },
      { level: 'middle', tapsiriq: 'Asinxron yükləmə modelini qur: coroutine ilə vəziyyəti dəyişdir.', starter: 'import kotlinx.coroutines.*\n\nclass ViewModel {\n    var veziyyet = "Yuklenir"\n        private set\n\n    suspend fun yukle() {\n        delay(50)\n        // veziyyeti deyisdir\n    }\n}\n\nfun main() {\n    runBlocking {\n        val vm = ViewModel()\n        println(vm.veziyyet)\n        vm.yukle()\n        println(vm.veziyyet)\n    }\n}', gozlenilen: 'Yuklenir\nUgurlu', ipucu: 'veziyyet = "Ugurlu"', hell: 'import kotlinx.coroutines.*\n\nclass ViewModel {\n    var veziyyet = "Yuklenir"\n        private set\n\n    suspend fun yukle() {\n        delay(50)\n        veziyyet = "Ugurlu"\n    }\n}\n\nfun main() {\n    runBlocking {\n        val vm = ViewModel()\n        println(vm.veziyyet)\n        vm.yukle()\n        println(vm.veziyyet)\n    }\n}' },
      { level: 'middle', tapsiriq: 'Xəta halını runCatching ilə vəziyyətə çevir.', starter: 'sealed interface V {\n    data class Ugurlu(val d: String) : V\n    data class Xeta(val m: String) : V\n}\n\nfun yukle(ugurlu: Boolean): V = runCatching {\n    if (ugurlu) "data" else error("sebeke xetasi")\n}.fold(\n    // onSuccess ve onFailure yaz\n)\n\nfun main() {\n    println(yukle(false))\n}', gozlenilen: 'Xeta(m=sebeke xetasi)', ipucu: 'onSuccess = { V.Ugurlu(it) }, onFailure = { V.Xeta(it.message ?: "namelum") }', hell: 'sealed interface V {\n    data class Ugurlu(val d: String) : V\n    data class Xeta(val m: String) : V\n}\n\nfun yukle(ugurlu: Boolean): V = runCatching {\n    if (ugurlu) "data" else error("sebeke xetasi")\n}.fold(\n    onSuccess = { V.Ugurlu(it) },\n    onFailure = { V.Xeta(it.message ?: "namelum") }\n)\n\nfun main() {\n    println(yukle(false))\n}' },
      { level: 'middle', tapsiriq: 'StateFlow modelini Flow ilə qur: vəziyyət dəyişikliklərini axın kimi ver.', starter: 'import kotlinx.coroutines.*\nimport kotlinx.coroutines.flow.*\n\nfun main() = runBlocking {\n    val veziyyet = MutableStateFlow("bos")\n    val is1 = launch {\n        veziyyet.take(2).collect { println(it) }\n    }\n    delay(50)\n    // veziyyeti deyisdir\n    is1.join()\n}', gozlenilen: 'bos\nhazir', ipucu: 'veziyyet.value = "hazir"', hell: 'import kotlinx.coroutines.*\nimport kotlinx.coroutines.flow.*\n\nfun main() = runBlocking {\n    val veziyyet = MutableStateFlow("bos")\n    val is1 = launch {\n        veziyyet.take(2).collect { println(it) }\n    }\n    delay(50)\n    veziyyet.value = "hazir"\n    is1.join()\n}' },
      { level: 'middle', tapsiriq: 'asStateFlow modelini qur: kənara yalnız-oxunan axın ver.', starter: 'import kotlinx.coroutines.flow.*\n\nclass ViewModel {\n    private val _veziyyet = MutableStateFlow(0)\n    // kenara yalniz-oxunan verin\n\n    fun artir() { _veziyyet.value++ }\n}\n\nfun main() {\n    val vm = ViewModel()\n    vm.artir()\n    println(vm.veziyyet.value)\n}', gozlenilen: '1', ipucu: 'val veziyyet: StateFlow<Int> = _veziyyet.asStateFlow()', hell: 'import kotlinx.coroutines.flow.*\n\nclass ViewModel {\n    private val _veziyyet = MutableStateFlow(0)\n    val veziyyet: StateFlow<Int> = _veziyyet.asStateFlow()\n\n    fun artir() { _veziyyet.value++ }\n}\n\nfun main() {\n    val vm = ViewModel()\n    vm.artir()\n    println(vm.veziyyet.value)\n}' },
      { level: 'middle', tapsiriq: 'Siyahını UI üçün qruplaşdır: elementləri ilk hərfə görə ayır.', starter: 'fun main() {\n    val s = listOf("Aysel", "Ayten", "Kamran")\n    // ilk herfe gore qruplasdir ve cap et\n}', gozlenilen: '{A=[Aysel, Ayten], K=[Kamran]}', ipucu: 's.groupBy { it.first() }', hell: 'fun main() {\n    val s = listOf("Aysel", "Ayten", "Kamran")\n    println(s.groupBy { it.first() })\n}' },
      { level: 'middle', tapsiriq: 'Axtarış filtri yaz: UI-dakı siyahını mətnə görə süz (böyük-kiçik hərf fərqi olmadan).', starter: 'fun main() {\n    val s = listOf("Kotlin", "Java", "Swift")\n    val sorgu = "a"\n    // boyuk-kicik herf ferqi olmadan suz\n}', gozlenilen: '[Java]', ipucu: 's.filter { it.contains(sorgu, ignoreCase = true) } — yalnız "Java" sözündə a hərfi var.', hell: 'fun main() {\n    val s = listOf("Kotlin", "Java", "Swift")\n    val sorgu = "a"\n    println(s.filter { it.contains(sorgu, ignoreCase = true) })\n}' },
      { level: 'senior', tapsiriq: 'Vəziyyət reduceri yaz: hadisəni cari vəziyyətə tətbiq et.', starter: 'data class Veziyyet(val say: Int = 0)\nsealed interface Hadise {\n    data object Artir : Hadise\n    data object Sifirla : Hadise\n}\n\nfun reduce(v: Veziyyet, h: Hadise): Veziyyet = when (h) {\n    // hadiseleri emal et\n}\n\nfun main() {\n    var v = Veziyyet()\n    v = reduce(v, Hadise.Artir)\n    v = reduce(v, Hadise.Artir)\n    println(v.say)\n}', gozlenilen: '2', ipucu: 'Hadise.Artir -> v.copy(say = v.say + 1)', hell: 'data class Veziyyet(val say: Int = 0)\nsealed interface Hadise {\n    data object Artir : Hadise\n    data object Sifirla : Hadise\n}\n\nfun reduce(v: Veziyyet, h: Hadise): Veziyyet = when (h) {\n    Hadise.Artir -> v.copy(say = v.say + 1)\n    Hadise.Sifirla -> Veziyyet()\n}\n\nfun main() {\n    var v = Veziyyet()\n    v = reduce(v, Hadise.Artir)\n    v = reduce(v, Hadise.Artir)\n    println(v.say)\n}' },
      { level: 'senior', tapsiriq: 'Reducer ilə sıfırlama hadisəsini sına.', starter: 'data class Veziyyet(val say: Int = 0)\nsealed interface Hadise {\n    data object Artir : Hadise\n    data object Sifirla : Hadise\n}\n\nfun reduce(v: Veziyyet, h: Hadise): Veziyyet = when (h) {\n    Hadise.Artir -> v.copy(say = v.say + 1)\n    Hadise.Sifirla -> Veziyyet()\n}\n\nfun main() {\n    // artir, artir, sifirla ardicilligini tetbiq et\n}', gozlenilen: '0', ipucu: 'fold işlət və ya ardıcıl reduce çağır.', hell: 'data class Veziyyet(val say: Int = 0)\nsealed interface Hadise {\n    data object Artir : Hadise\n    data object Sifirla : Hadise\n}\n\nfun reduce(v: Veziyyet, h: Hadise): Veziyyet = when (h) {\n    Hadise.Artir -> v.copy(say = v.say + 1)\n    Hadise.Sifirla -> Veziyyet()\n}\n\nfun main() {\n    val son = listOf(Hadise.Artir, Hadise.Artir, Hadise.Sifirla)\n        .fold(Veziyyet()) { v, h -> reduce(v, h) }\n    println(son.say)\n}' },
      { level: 'senior', tapsiriq: 'State hoisting modelini göstər: vəziyyətsiz komponent yaz.', starter: '// veziyyetsiz komponent: deyeri ve dəyişdiriciyi parametr kimi alir\nfun sayqacGoster(deyer: Int, artir: () -> Unit): String {\n    artir()\n    return "Sayqac: $deyer"\n}\n\nfun main() {\n    var say = 0\n    // komponenti cagir\n}', gozlenilen: 'Sayqac: 0\n1', ipucu: 'println(sayqacGoster(say) { say++ }) sonra println(say)', hell: 'fun sayqacGoster(deyer: Int, artir: () -> Unit): String {\n    artir()\n    return "Sayqac: $deyer"\n}\n\nfun main() {\n    var say = 0\n    println(sayqacGoster(say) { say++ })\n    println(say)\n}' },
      { level: 'senior', tapsiriq: 'Bir dəfəlik hadisəni Channel ilə modelləşdir.', starter: 'import kotlinx.coroutines.*\nimport kotlinx.coroutines.channels.*\n\nfun main() = runBlocking {\n    val hadiseler = Channel<String>()\n    launch {\n        // bir hadise gonder ve bagla\n    }\n    for (h in hadiseler) println(h)\n}', gozlenilen: 'toast: salam', ipucu: 'hadiseler.send("toast: salam") sonra hadiseler.close()', hell: 'import kotlinx.coroutines.*\nimport kotlinx.coroutines.channels.*\n\nfun main() = runBlocking {\n    val hadiseler = Channel<String>()\n    launch {\n        hadiseler.send("toast: salam")\n        hadiseler.close()\n    }\n    for (h in hadiseler) println(h)\n}' },
      { level: 'senior', tapsiriq: 'Room DAO-nun Flow qaytarmasını modelləşdir: dəyişiklikdə yeni siyahı gəlsin.', starter: 'import kotlinx.coroutines.*\nimport kotlinx.coroutines.flow.*\n\nfun main() = runBlocking {\n    val baza = MutableStateFlow(listOf("alma"))\n    val is1 = launch {\n        baza.take(2).collect { println(it) }\n    }\n    delay(50)\n    // bazaya yeni element elave et\n    is1.join()\n}', gozlenilen: '[alma]\n[alma, armud]', ipucu: 'baza.value = baza.value + "armud"', hell: 'import kotlinx.coroutines.*\nimport kotlinx.coroutines.flow.*\n\nfun main() = runBlocking {\n    val baza = MutableStateFlow(listOf("alma"))\n    val is1 = launch {\n        baza.take(2).collect { println(it) }\n    }\n    delay(50)\n    baza.value = baza.value + "armud"\n    is1.join()\n}' },
      { level: 'senior', tapsiriq: 'Scope ləğvini modelləşdir: sahə bağlananda iş dayansın.', starter: 'import kotlinx.coroutines.*\n\nfun main() = runBlocking {\n    val scope = CoroutineScope(Dispatchers.Default)\n    scope.launch {\n        try {\n            repeat(100) { delay(50) }\n        } finally {\n            println("temizlendi")\n        }\n    }\n    delay(120)\n    // scope-u legv et\n    delay(50)\n}', gozlenilen: 'temizlendi', ipucu: 'scope.cancel() — ViewModel məhv olanda viewModelScope da belə ləğv olunur.', hell: 'import kotlinx.coroutines.*\n\nfun main() = runBlocking {\n    val scope = CoroutineScope(Dispatchers.Default)\n    scope.launch {\n        try {\n            repeat(100) { delay(50) }\n        } finally {\n            println("temizlendi")\n        }\n    }\n    delay(120)\n    scope.cancel()\n    delay(50)\n}' }
    ]
