    praktiki: [
      { level: 'junior', tapsiriq: 'Platforma abstraksiyası qur: interfeys elan et və bir implementasiya yaz.', starter: 'interface Platforma {\n    fun ad(): String\n}\n\n// Android implementasiyasini yaz\n\nfun main() {\n    val p: Platforma = AndroidPlatforma()\n    println(p.ad())\n}', gozlenilen: 'Android 34', ipucu: 'class AndroidPlatforma : Platforma { override fun ad() = "Android 34" }', hell: 'interface Platforma {\n    fun ad(): String\n}\n\nclass AndroidPlatforma : Platforma {\n    override fun ad() = "Android 34"\n}\n\nfun main() {\n    val p: Platforma = AndroidPlatforma()\n    println(p.ad())\n}' },
      { level: 'junior', tapsiriq: 'İki platforma implementasiyası yaz və hər ikisini çağır.', starter: 'interface Platforma { fun ad(): String }\n\n// iki implementasiya yaz\n\nfun main() {\n    listOf(AndroidPlatforma(), IosPlatforma()).forEach { println(it.ad()) }\n}', gozlenilen: 'Android\niOS', ipucu: 'İki sinif yaz, hər biri Platforma implement etsin.', hell: 'interface Platforma { fun ad(): String }\n\nclass AndroidPlatforma : Platforma {\n    override fun ad() = "Android"\n}\n\nclass IosPlatforma : Platforma {\n    override fun ad() = "iOS"\n}\n\nfun main() {\n    listOf(AndroidPlatforma(), IosPlatforma()).forEach { println(it.ad()) }\n}' },
      { level: 'junior', tapsiriq: 'Ortaq biznes məntiqi yaz: platformadan asılı olmayan salamlama.', starter: 'interface Platforma { fun ad(): String }\n\nclass SalamlamaServisi(private val p: Platforma) {\n    // salamla() metodunu yaz\n}\n\nfun main() {\n    val saxta = object : Platforma { override fun ad() = "Test" }\n    println(SalamlamaServisi(saxta).salamla())\n}', gozlenilen: 'Salam, Test!', ipucu: 'fun salamla() = "Salam, ${p.ad()}!"', hell: 'interface Platforma { fun ad(): String }\n\nclass SalamlamaServisi(private val p: Platforma) {\n    fun salamla() = "Salam, ${p.ad()}!"\n}\n\nfun main() {\n    val saxta = object : Platforma { override fun ad() = "Test" }\n    println(SalamlamaServisi(saxta).salamla())\n}' },
      { level: 'junior', tapsiriq: 'Ortaq data modeli yaz: platformadan asılı olmayan istifadəçi.', starter: '// ortaq data class yaz\n\nfun main() {\n    println(Istifadeci(1, "Aysel"))\n}', gozlenilen: 'Istifadeci(id=1, ad=Aysel)', ipucu: 'data class Istifadeci(val id: Int, val ad: String)', hell: 'data class Istifadeci(val id: Int, val ad: String)\n\nfun main() {\n    println(Istifadeci(1, "Aysel"))\n}' },
      { level: 'junior', tapsiriq: 'Ortaq validasiya məntiqi yaz: email yoxlaması.', starter: '// ortaq validasiya funksiyasi yaz\n\nfun main() {\n    println(emailDuzgundur("aysel@mail.az"))\n    println(emailDuzgundur("yanlis"))\n}', gozlenilen: 'true\nfalse', ipucu: 'fun emailDuzgundur(e: String) = e.contains("@") && e.contains(".")', hell: 'fun emailDuzgundur(e: String) = e.contains("@") && e.contains(".")\n\nfun main() {\n    println(emailDuzgundur("aysel@mail.az"))\n    println(emailDuzgundur("yanlis"))\n}' },
      { level: 'junior', tapsiriq: 'Ortaq sabitlər üçün object işlət.', starter: '// ortaq konfiq object-i yaz\n\nfun main() {\n    println(Konfiq.API_URL)\n}', gozlenilen: 'https://api.numune.az', ipucu: 'object Konfiq { const val API_URL = "https://api.numune.az" }', hell: 'object Konfiq {\n    const val API_URL = "https://api.numune.az"\n}\n\nfun main() {\n    println(Konfiq.API_URL)\n}' },
      { level: 'junior', tapsiriq: 'Platformaya görə fərqli davranış: interfeysi parametr kimi ötür.', starter: 'interface Platforma { fun ad(): String }\n\nfun tesvir(p: Platforma) = "Isleyir: ${p.ad()}"\n\nfun main() {\n    // anonim obyekt ile cagir\n}', gozlenilen: 'Isleyir: Desktop', ipucu: 'println(tesvir(object : Platforma { override fun ad() = "Desktop" }))', hell: 'interface Platforma { fun ad(): String }\n\nfun tesvir(p: Platforma) = "Isleyir: ${p.ad()}"\n\nfun main() {\n    println(tesvir(object : Platforma {\n        override fun ad() = "Desktop"\n    }))\n}' },
      { level: 'junior', tapsiriq: 'Ortaq nəticə tipi yaz: sealed ilə uğur/xəta modeli.', starter: '// ortaq sealed netice tipi yaz\n\nfun main() {\n    val n: Netice = Netice.Ugur("data")\n    println(n)\n}', gozlenilen: 'Ugur(data=data)', ipucu: 'sealed interface Netice { data class Ugur(val data: String) : Netice; data class Xeta(val kod: Int) : Netice }', hell: 'sealed interface Netice {\n    data class Ugur(val data: String) : Netice\n    data class Xeta(val kod: Int) : Netice\n}\n\nfun main() {\n    val n: Netice = Netice.Ugur("data")\n    println(n)\n}' },
      { level: 'junior', tapsiriq: 'Ortaq genişlənmə yaz: mətni slug formasına salsın.', starter: '// ortaq genislenme yaz\n\nfun main() {\n    println("Kotlin Multiplatform".slugla())\n}', gozlenilen: 'kotlin-multiplatform', ipucu: 'fun String.slugla() = lowercase().replace(" ", "-")', hell: 'fun String.slugla() = lowercase().replace(" ", "-")\n\nfun main() {\n    println("Kotlin Multiplatform".slugla())\n}' },
      { level: 'middle', tapsiriq: 'Platforma abstraksiyasını test et: saxta implementasiya ötür.', starter: 'interface Saat {\n    fun indi(): Long\n}\n\nclass Servis(private val s: Saat) {\n    fun damga() = "vaxt: ${s.indi()}"\n}\n\nfun main() {\n    // sabit deyer qaytaran saxta Saat yarat\n}', gozlenilen: 'vaxt: 1000', ipucu: 'object : Saat { override fun indi() = 1000L } — testdə vaxt sabit olmalıdır.', hell: 'interface Saat {\n    fun indi(): Long\n}\n\nclass Servis(private val s: Saat) {\n    fun damga() = "vaxt: ${s.indi()}"\n}\n\nfun main() {\n    val saxta = object : Saat { override fun indi() = 1000L }\n    println(Servis(saxta).damga())\n}' },
      { level: 'middle', tapsiriq: 'Ortaq repozitoriya yaz: mənbə interfeysdən gəlsin.', starter: 'interface Menbe { fun al(): List<String> }\n\nclass Repo(private val m: Menbe) {\n    // hamisi() metodunu yaz - sirali qaytarsin\n}\n\nfun main() {\n    val saxta = object : Menbe { override fun al() = listOf("b", "a") }\n    println(Repo(saxta).hamisi())\n}', gozlenilen: '[a, b]', ipucu: 'fun hamisi() = m.al().sorted()', hell: 'interface Menbe { fun al(): List<String> }\n\nclass Repo(private val m: Menbe) {\n    fun hamisi() = m.al().sorted()\n}\n\nfun main() {\n    val saxta = object : Menbe { override fun al() = listOf("b", "a") }\n    println(Repo(saxta).hamisi())\n}' },
      { level: 'middle', tapsiriq: 'Ortaq ViewModel modelini qur: vəziyyət platformadan asılı olmasın.', starter: 'import kotlinx.coroutines.flow.*\n\nclass OrtakViewModel {\n    private val _v = MutableStateFlow("bos")\n    val v: StateFlow<String> = _v.asStateFlow()\n    // yukle() metodunu yaz\n}\n\nfun main() {\n    val vm = OrtakViewModel()\n    vm.yukle()\n    println(vm.v.value)\n}', gozlenilen: 'hazir', ipucu: 'fun yukle() { _v.value = "hazir" }', hell: 'import kotlinx.coroutines.flow.*\n\nclass OrtakViewModel {\n    private val _v = MutableStateFlow("bos")\n    val v: StateFlow<String> = _v.asStateFlow()\n    fun yukle() { _v.value = "hazir" }\n}\n\nfun main() {\n    val vm = OrtakViewModel()\n    vm.yukle()\n    println(vm.v.value)\n}' },
      { level: 'middle', tapsiriq: 'Ortaq suspend məntiq yaz: platformadan asılı olmayan asinxron əməliyyat.', starter: 'import kotlinx.coroutines.*\n\n// ortaq suspend funksiya yaz\n\nfun main() = runBlocking {\n    println(melumatYukle())\n}', gozlenilen: 'melumat hazirdir', ipucu: 'suspend fun melumatYukle(): String { delay(50); return "melumat hazirdir" }', hell: 'import kotlinx.coroutines.*\n\nsuspend fun melumatYukle(): String {\n    delay(50)\n    return "melumat hazirdir"\n}\n\nfun main() = runBlocking {\n    println(melumatYukle())\n}' },
      { level: 'middle', tapsiriq: 'Ortaq xəta modelini emal et: when ilə hər halı idarə et.', starter: 'sealed interface Netice {\n    data class Ugur(val d: String) : Netice\n    data class Xeta(val kod: Int) : Netice\n}\n\nfun emal(n: Netice): String = when (n) {\n    // hallari emal et\n}\n\nfun main() {\n    println(emal(Netice.Xeta(503)))\n}', gozlenilen: 'Xeta kodu: 503', ipucu: 'is Netice.Xeta -> "Xeta kodu: ${n.kod}"', hell: 'sealed interface Netice {\n    data class Ugur(val d: String) : Netice\n    data class Xeta(val kod: Int) : Netice\n}\n\nfun emal(n: Netice): String = when (n) {\n    is Netice.Ugur -> "Data: ${n.d}"\n    is Netice.Xeta -> "Xeta kodu: ${n.kod}"\n}\n\nfun main() {\n    println(emal(Netice.Xeta(503)))\n}' },
      { level: 'middle', tapsiriq: 'Ortaq formatlaşdırma yaz: lokaldan asılı olmayan şəkildə.', starter: '// ortaq funksiya yaz - qiymeti "1200 AZN" formasinda versin\n\nfun main() {\n    println(qiymetFormatla(1200))\n}', gozlenilen: '1200 AZN', ipucu: 'fun qiymetFormatla(q: Int) = "$q AZN" — String.format lokaldan asılıdır, ondan qaç.', hell: 'fun qiymetFormatla(q: Int) = "$q AZN"\n\nfun main() {\n    println(qiymetFormatla(1200))\n}' },
      { level: 'middle', tapsiriq: 'Ortaq keş modeli qur: map ilə sadə saxlama.', starter: 'class Kes {\n    private val m = mutableMapOf<String, String>()\n    // yaz() ve oxu() metodlarini yaz\n}\n\nfun main() {\n    val k = Kes()\n    k.yaz("ad", "Aysel")\n    println(k.oxu("ad"))\n    println(k.oxu("yoxdur"))\n}', gozlenilen: 'Aysel\nnull', ipucu: 'fun yaz(a: String, d: String) { m[a] = d } və fun oxu(a: String) = m[a]', hell: 'class Kes {\n    private val m = mutableMapOf<String, String>()\n    fun yaz(a: String, d: String) { m[a] = d }\n    fun oxu(a: String) = m[a]\n}\n\nfun main() {\n    val k = Kes()\n    k.yaz("ad", "Aysel")\n    println(k.oxu("ad"))\n    println(k.oxu("yoxdur"))\n}' },
      { level: 'middle', tapsiriq: 'Ortaq test yaz: platformadan asılı olmayan məntiqi yoxla.', starter: 'import kotlin.test.assertEquals\n\nfun emailDuzgundur(e: String) = e.contains("@")\n\nfun main() {\n    // iki hali yoxla\n    println("kecdi")\n}', gozlenilen: 'kecdi', ipucu: 'assertEquals(true, emailDuzgundur("a@b")) və assertEquals(false, emailDuzgundur("x"))', hell: 'import kotlin.test.assertEquals\n\nfun emailDuzgundur(e: String) = e.contains("@")\n\nfun main() {\n    assertEquals(true, emailDuzgundur("a@b"))\n    assertEquals(false, emailDuzgundur("x"))\n    println("kecdi")\n}' },
      { level: 'middle', tapsiriq: 'Platformaya görə fərqli konfiq seç: map ilə modelləşdir.', starter: 'fun konfiq(platforma: String): String = when (platforma) {\n    // android ve ios ucun fergli url, qalanlar ucun defolt\n}\n\nfun main() {\n    println(konfiq("ios"))\n}', gozlenilen: 'https://ios.api.az', ipucu: '"ios" -> "https://ios.api.az"', hell: 'fun konfiq(platforma: String): String = when (platforma) {\n    "android" -> "https://android.api.az"\n    "ios" -> "https://ios.api.az"\n    else -> "https://api.az"\n}\n\nfun main() {\n    println(konfiq("ios"))\n}' },
      { level: 'middle', tapsiriq: 'Ortaq siyahı emalı yaz: hər platformada eyni nəticə versin.', starter: 'fun aktivler(s: List<Pair<String, Boolean>>): List<String> {\n    // yalniz aktiv olanlarin adlarini qaytar\n}\n\nfun main() {\n    println(aktivler(listOf("a" to true, "b" to false, "c" to true)))\n}', gozlenilen: '[a, c]', ipucu: 's.filter { it.second }.map { it.first }', hell: 'fun aktivler(s: List<Pair<String, Boolean>>): List<String> {\n    return s.filter { it.second }.map { it.first }\n}\n\nfun main() {\n    println(aktivler(listOf("a" to true, "b" to false, "c" to true)))\n}' },
      { level: 'senior', tapsiriq: 'Fabrik funksiyası yaz: platformaya uyğun implementasiya qaytarsın.', starter: 'interface Platforma { fun ad(): String }\nclass Android : Platforma { override fun ad() = "Android" }\nclass Ios : Platforma { override fun ad() = "iOS" }\n\nfun yarat(hedef: String): Platforma = when (hedef) {\n    // uygun implementasiyani qaytar\n}\n\nfun main() {\n    println(yarat("ios").ad())\n}', gozlenilen: 'iOS', ipucu: '"ios" -> Ios() və else -> Android()', hell: 'interface Platforma { fun ad(): String }\nclass Android : Platforma { override fun ad() = "Android" }\nclass Ios : Platforma { override fun ad() = "iOS" }\n\nfun yarat(hedef: String): Platforma = when (hedef) {\n    "ios" -> Ios()\n    else -> Android()\n}\n\nfun main() {\n    println(yarat("ios").ad())\n}' },
      { level: 'senior', tapsiriq: 'Ortaq ViewModel-i test et: saxta repozitoriya ilə vəziyyəti yoxla.', starter: 'import kotlinx.coroutines.*\nimport kotlinx.coroutines.flow.*\nimport kotlin.test.assertEquals\n\ninterface Repo { suspend fun al(): String }\n\nclass VM(private val r: Repo) {\n    private val _v = MutableStateFlow("bos")\n    val v: StateFlow<String> = _v.asStateFlow()\n    suspend fun yukle() { _v.value = r.al() }\n}\n\nfun main() = runBlocking {\n    val saxta = object : Repo { override suspend fun al() = "test-data" }\n    val vm = VM(saxta)\n    vm.yukle()\n    // veziyyeti yoxla\n    println("kecdi")\n}', gozlenilen: 'kecdi', ipucu: 'assertEquals("test-data", vm.v.value)', hell: 'import kotlinx.coroutines.*\nimport kotlinx.coroutines.flow.*\nimport kotlin.test.assertEquals\n\ninterface Repo { suspend fun al(): String }\n\nclass VM(private val r: Repo) {\n    private val _v = MutableStateFlow("bos")\n    val v: StateFlow<String> = _v.asStateFlow()\n    suspend fun yukle() { _v.value = r.al() }\n}\n\nfun main() = runBlocking {\n    val saxta = object : Repo { override suspend fun al() = "test-data" }\n    val vm = VM(saxta)\n    vm.yukle()\n    assertEquals("test-data", vm.v.value)\n    println("kecdi")\n}' },
      { level: 'senior', tapsiriq: 'Ortaq kodda generik keş yaz: istənilən tip üçün işləsin.', starter: 'class Kes<K, V> {\n    private val m = mutableMapOf<K, V>()\n    // yaz ve oxu metodlarini yaz\n}\n\nfun main() {\n    val k = Kes<Int, String>()\n    k.yaz(1, "bir")\n    println(k.oxu(1))\n}', gozlenilen: 'bir', ipucu: 'fun yaz(a: K, d: V) { m[a] = d } və fun oxu(a: K): V? = m[a]', hell: 'class Kes<K, V> {\n    private val m = mutableMapOf<K, V>()\n    fun yaz(a: K, d: V) { m[a] = d }\n    fun oxu(a: K): V? = m[a]\n}\n\nfun main() {\n    val k = Kes<Int, String>()\n    k.yaz(1, "bir")\n    println(k.oxu(1))\n}' },
      { level: 'senior', tapsiriq: 'Ortaq şəbəkə qatının modelini qur: interfeys + saxta cavab.', starter: 'import kotlinx.coroutines.*\n\ninterface HttpClient {\n    suspend fun get(url: String): String\n}\n\nclass Api(private val c: HttpClient) {\n    // istifadeciler() metodunu yaz\n}\n\nfun main() = runBlocking {\n    val saxta = object : HttpClient {\n        override suspend fun get(url: String) = "[Aysel]"\n    }\n    println(Api(saxta).istifadeciler())\n}', gozlenilen: '[Aysel]', ipucu: 'suspend fun istifadeciler() = c.get("/istifadeciler")', hell: 'import kotlinx.coroutines.*\n\ninterface HttpClient {\n    suspend fun get(url: String): String\n}\n\nclass Api(private val c: HttpClient) {\n    suspend fun istifadeciler() = c.get("/istifadeciler")\n}\n\nfun main() = runBlocking {\n    val saxta = object : HttpClient {\n        override suspend fun get(url: String) = "[Aysel]"\n    }\n    println(Api(saxta).istifadeciler())\n}' },
      { level: 'senior', tapsiriq: 'Ortaq məntiqin platformadan asılı olmadığını göstər: eyni servis iki platforma ilə.', starter: 'interface Platforma { fun ad(): String }\n\nclass Servis(private val p: Platforma) {\n    fun tesvir() = "Servis ${p.ad()} uzerinde isleyir"\n}\n\nfun main() {\n    val a = object : Platforma { override fun ad() = "Android" }\n    val i = object : Platforma { override fun ad() = "iOS" }\n    // her ikisi ucun cap et\n}', gozlenilen: 'Servis Android uzerinde isleyir\nServis iOS uzerinde isleyir', ipucu: 'listOf(a, i).forEach { println(Servis(it).tesvir()) }', hell: 'interface Platforma { fun ad(): String }\n\nclass Servis(private val p: Platforma) {\n    fun tesvir() = "Servis ${p.ad()} uzerinde isleyir"\n}\n\nfun main() {\n    val a = object : Platforma { override fun ad() = "Android" }\n    val i = object : Platforma { override fun ad() = "iOS" }\n    listOf(a, i).forEach { println(Servis(it).tesvir()) }\n}' },
      { level: 'senior', tapsiriq: 'Ortaq kodda Result işlət: platformadan asılı olmayan xəta emalı.', starter: 'fun yukle(ugurlu: Boolean): Result<String> = runCatching {\n    if (ugurlu) "data" else error("xeta")\n}\n\nfun main() {\n    // ugursuz hali emal et ve ehtiyat deyer cap et\n}', gozlenilen: 'defolt', ipucu: 'println(yukle(false).getOrDefault("defolt"))', hell: 'fun yukle(ugurlu: Boolean): Result<String> = runCatching {\n    if (ugurlu) "data" else error("xeta")\n}\n\nfun main() {\n    println(yukle(false).getOrDefault("defolt"))\n}' }
    ]
